'Custom_SMS_Payload_Hint' => 'Defina os campos do corpo da requisição. Use {phone}, {message} e {sender} como placeholders; eles serão substituídos no momento do envio.',
'Custom_SMS_Guide_Title' => 'Como configurar',
'Custom_SMS_Guide_Intro' => 'Qualquer provedor de SMS com API HTTP pode ser conectado. Abra a documentação da API do seu provedor, copie o endpoint, o método e os nomes dos campos e mapeie-os abaixo usando os placeholders.',
'Custom_SMS_Guide_Placeholder_Phone' => 'o número de telefone do destinatário',
'Custom_SMS_Guide_Placeholder_Message' => 'o texto do SMS',
'Custom_SMS_Guide_Placeholder_Sender' => 'o ID do Remetente informado acima',
'Custom_SMS_Guide_Api_Url' => 'A URL completa do endpoint, conforme a documentação do seu provedor, ex.: https://api.provider.com/sms/send. Placeholders também podem ser usados diretamente na URL, ex.: ...?to={phone}&text={message}.',
'Custom_SMS_Guide_Method' => 'POST é o mais comum. Escolha GET apenas se o seu provedor esperar tudo na URL — nesse caso, os campos do payload são enviados como parâmetros de consulta.',
'Custom_SMS_Guide_Content_Type' => '"json" envia o payload como corpo JSON (application/json). "form" envia como um formulário HTML clássico (application/x-www-form-urlencoded). Verifique qual deles o seu provedor espera; é ignorado para GET.',
'Custom_SMS_Guide_Sender' => 'Seu ID de Remetente aprovado ou número de telefone de envio. Ele apenas preenche o placeholder {sender} — para ser transmitido, precisa ser usado no payload, nos cabeçalhos ou na URL.',
'Custom_SMS_Guide_Success_Keyword' => 'Opcional, mas recomendado. Alguns provedores respondem "200 OK" mesmo quando o envio falha. Informe uma palavra ou trecho que só aparece em uma resposta bem-sucedida (ex.: success). Se a resposta não contiver esse texto, o SMS é considerado como falho.',
'Custom_SMS_Guide_Headers' => 'Cabeçalhos de autenticação exigidos pelo seu provedor, ex.: Authorization = Bearer YOUR_API_KEY ou Api-Key = YOUR_API_KEY. Não adicione Content-Type — ele é definido automaticamente.',
'Custom_SMS_Guide_Payload' => 'Os campos do corpo da requisição, nomeados exatamente como na documentação do seu provedor. Use os placeholders como valores, ex.: to = {phone}, message = {message}, from = {sender}.',
'Custom_SMS_Guide_Example' => 'Exemplo completo',
'Custom_SMS_Guide_Default_Note' => 'Depois de salvar, selecione "custom" como Gateway de SMS Padrão no topo desta página e envie — caso contrário, os SMS continuarão usando o gateway selecionado anteriormente.',
