'Cr_Guide_T_Statuses' => 'Status',
'Cr_Guide_Statuses_Note' => 'Os status só avançam, então uma atualização atrasada nunca faz uma encomenda voltar. Uma encomenda entregue ainda pode ser informada como em devolução ou devolvida.',
'Cr_Guide_S_booked' => 'A transportadora tem o pedido; ninguém o coletou ainda. Um envio só pode ser cancelado agora.',
