'Cr_Guide_S_returning' => 'A caminho de volta para você.',
'Cr_Guide_S_returned' => 'De volta com você: aguarda em Devoluções para revisão, ou volta ao estoque automaticamente.',
'Cr_Guide_S_cancelled' => 'O envio foi cancelado.',
'Cr_Guide_T_Booking' => 'Registro de pedidos',
'Cr_Guide_B_Booking' => 'Enviar à transportadora preenche o formulário a partir da venda: destinatário, endereço, o valor ainda devido como COD e o peso dos produtos. Transportadoras com listas de cidades próprias mostram um seletor, e sua escolha é lembrada para aquela cidade. Agregadores, DHL, FedEx, UPS e Lalamove oferecem Comparar tarifas: escolha um preço e Registrar o contrata. Várias vendas podem ser registradas de uma vez pela lista de vendas.',
'Cr_Guide_T_Cod' => 'Pagamento na entrega',
'Cr_Guide_B_Cod' => 'Uma encomenda COD passa de Não recebido para Recebido pela transportadora (na entrega) e depois para Repassado a você. Transportadoras que informam repasses avançam a última etapa sozinhas; para as demais, use Atualizar COD. Com uma conta escolhida em Configurações da transportadora, o repasse é registrado como pagamento na venda. As tarifas da transportadora podem ser salvas como despesa assim que a encomenda for finalizada.',
'Cr_Guide_T_Returns' => 'Encomendas devolvidas',
'Cr_Guide_B_Returns' => 'Por padrão, uma encomenda devolvida aguarda em Envios da transportadora, em Devoluções, para revisão. Repor estoque cria uma devolução de venda para o pedido inteiro e coloca os itens de volta no estoque; Descartar não repõe nada, para encomendas danificadas ou perdidas. As Configurações da transportadora podem repor o estoque automaticamente.',
'Cr_Guide_T_Customers' => 'Mensagens aos clientes e página de rastreamento',
'Cr_Guide_B_Customers' => 'As notificações ao cliente em Configurações da transportadora enviam SMS, e-mail ou WhatsApp nos status que você marcar, uma vez por encomenda, com o seu próprio texto. A página de rastreamento na sua loja online permite que os clientes acompanhem a encomenda pelo código de rastreamento ou pelo número do pedido e telefone. Clientes que devolvem encomendas com frequência recebem um selo de risco de devolução quando você registra o envio.',
'Cr_Guide_T_Labels' => 'Etiquetas',
'Cr_Guide_B_Labels' => 'Imprimir etiqueta gera a etiqueta da própria transportadora quando ela emite uma (um PDF, um link ou uma imagem); caso contrário, uma etiqueta do Stocky com o código de barras de rastreamento e o valor a receber. Permita pop-ups para este site para imprimir. DHL, FedEx e UPS fornecem a etiqueta apenas uma vez, no registro do envio, e o Stocky a guarda para reimpressões.',
'Cr_Guide_T_Faq' => 'Solução de problemas',
'Cr_Guide_Q_Test' => 'O teste de conexão falha',
'Cr_Guide_A_Test' => 'Chaves de teste funcionam com o Modo de teste e chaves de produção com Produção; elas são diferentes. Abra Logs da transportadora e leia a resposta da transportadora para saber o motivo exato.',
'Cr_Guide_Q_City' => 'A transportadora rejeita a cidade ou o endereço',
'Cr_Guide_A_City' => 'Escolha a cidade na lista de cidades da transportadora no formulário de registro; as transportadoras só aceitam os próprios nomes. Transportadoras que trabalham com endereços postais também precisam do estado, do CEP e do país com duas letras.',
'Cr_Guide_Q_Webhook' => 'Os status não mudam sozinhos',
'Cr_Guide_A_Webhook' => 'Para transportadoras que enviam atualizações, verifique se a URL do webhook está registrada na transportadora: Logs da transportadora mostra cada atualização recebida, ou por que uma foi rejeitada (por exemplo, um segredo errado). As demais transportadoras são verificadas conforme o agendamento em Configurações da transportadora, e Verificar status agora consulta na hora.',
'Cr_Guide_Q_Stuck' => 'Um envio mostra um erro de verificação de status',
'Cr_Guide_A_Stuck' => 'A transportadora recusou as últimas verificações; o motivo aparece no envio e em Logs da transportadora. Após falhas repetidas, o envio deixa de ser verificado automaticamente: corrija a causa e use Verificar status agora.',
'Cr_Guide_Q_Label' => 'Nada abre ao imprimir uma etiqueta',
'Cr_Guide_A_Label' => 'Seu navegador bloqueou o pop-up. Permita pop-ups para este site e tente novamente.',
'Cr_Guide_Q_Cod' => 'Um repasse COD não foi registrado na venda',
'Cr_Guide_A_Cod' => 'Em Configurações da transportadora, o pagamento na entrega precisa estar ativado e com uma conta escolhida. Sem conta, os repasses são apenas marcados como repassados.',
