'Restrict_Master_Data_By_Warehouse' => 'Restringir cadastros por armazém',
'Restrict_Master_Data_By_Warehouse_Help' => 'Quando ativado, um usuário vinculado a armazéns específicos vê apenas os produtos, clientes, fornecedores, marcas e categorias ligados a esses armazéns. Registros ainda não usados em lugar nenhum continuam visíveis, para que os recém-criados nunca fiquem ocultos. Vendas, compras e devoluções são sempre restritas e não são afetadas por esta opção.',
'Restrict_Products_By_Warehouse' => 'Restringir produtos por armazém',
'Restrict_Products_By_Warehouse_Help' => 'Todo produto recebe um armazém de origem — a filial para a qual foi criado. Quando ativado, um usuário vinculado a armazéns específicos vê, vende e edita apenas os produtos cujo armazém de origem é um dos seus, além dos produtos que têm estoque real em um dos seus armazéns (transferidos ou comprados para lá). Usuários com acesso a todos os armazéns sempre veem tudo. A loja online segue a mesma regra: lista apenas os produtos dos armazéns selecionados nas Configurações da loja.',
'Virtual_Combo_Stock' => 'Estoque virtual de combos',
'Virtual_Combo_Stock_Help' => 'Quando ativado, um produto combo não tem estoque próprio: sua disponibilidade é o número de combos que os produtos componentes ainda conseguem montar, e vender um combo baixa o estoque dos componentes. Quando desativado, os combos são montados em estoque primeiro com um Ajuste.',
'Virtual_Combo_Stock_Warning' => 'O ideal é escolher antes de vender combos. Depois que combos forem vendidos ou devolvidos, alternar esta opção faz com que edições, exclusões e devoluções posteriores desses documentos revertam o estoque da forma errada.',
'Virtual_Combo_Stock_Confirm_On_Title' => 'Ativar o estoque virtual de combos?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'Os combos serão vendidos diretamente a partir dos produtos componentes, e o estoque próprio deles deixará de ser usado.',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'Desativar o estoque virtual de combos?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'Os combos voltarão a usar o próprio estoque, que precisa ser montado a partir dos componentes com um Ajuste antes que possam ser vendidos.',
'Home_Warehouse' => 'Armazém de origem',
'Home_Warehouse_Hint' => 'A filial à qual este produto pertence. Usuários restritos a outros armazéns não o verão, a menos que o estoque seja transferido para eles.',
'Home_Warehouse_Required' => 'Escolha o armazém ao qual este produto pertence.',
'Combo_products_required' => 'Adicione pelo menos um produto ao combo.',
'Customer_Performance_Help' => 'Mostra uma pontuação de desempenho e uma avaliação na página do cliente, calculadas a partir da confiabilidade de pagamento, de quão recentemente ele comprou e da taxa de devolução.',
'Product_Supplier' => 'Fornecedor nos produtos',
'Product_Supplier_Help' => 'Adiciona um campo de fornecedor padrão ao formulário do produto, exibe-o como coluna na lista de produtos e permite filtrar os produtos por fornecedor para montar uma lista de reposição.',
