'Tg_Guide_A_Title' => 'Na hora — nada para instalar',
'Tg_Guide_A_Body' => 'Uma venda, compra, pagamento ou despesa salvo no Stocky — no PDV ou no painel administrativo — é enviado ao Telegram {rightAfter} ser salvo, na mesma requisição. Sem entrada no cron, sem worker de fila, e o caixa nunca espera pelo Telegram: a venda já foi respondida quando a mensagem sai.',
'Tg_Guide_Right_After' => 'logo após',
'Tg_Guide_B_Title' => 'A entrada do cron — para novas tentativas e eventos em segundo plano',
'Tg_Guide_B_Body' => 'Dois tipos de mensagem aguardam na fila própria do Telegram: um envio que falhou (Telegram inacessível por um momento), que é tentado novamente até mais três vezes nos minutos seguintes; e eventos gerados fora do painel administrativo — pedidos importados do WooCommerce ou do Shopify, comandos artisan. Esta entrada do cron os envia, e nada mais:',
'Tg_Guide_B_Note' => 'A cada minuto é o ideal: uma execução sem nada pendente termina na hora. No cPanel, isso vai em {cronJobs} — use o caminho completo para o PHP 8.2+ se {php} for mais antigo. No Windows, use o Agendador de Tarefas com o programa {php2}, os argumentos {args}, iniciado em {path}.',
