'Tg_Guide_Err_400' => '{code} — ID do chat errado, ou o bot não está no grupo. Para um chat pessoal, mande uma mensagem ao bot primeiro.',
'Tg_Guide_Err_403' => '{code} — adicione o bot de volta ao grupo, ou como administrador do canal.',
'Tg_Guide_Test_Works' => 'O teste funciona, mas as vendas não',
