'Tg_Guide_Imported_Never' => 'Pedidos importados nunca chegam',
'Tg_Guide_Imported_Never_Item' => '{label} — a entrada do cron acima não está em execução.',
'Jumia_Hero_Title' => 'Sincronização com o marketplace Jumia',
'Jumia_Hero_Desc' => 'Envie preços e estoque para seus anúncios no Jumia Seller Center e importe pedidos do marketplace como vendas.',
'Jumia_Api_Url_Label' => 'URL da API (endpoint do Seller Center do seu país)',
'Jumia_Account_Email' => 'E-mail da conta (User ID)',
'Jumia_Prices_Stock' => 'Preços e Estoque',
'Jumia_Push_Card_Title' => 'Enviar preços e estoque para a Jumia',
'Jumia_Push_Desc' => 'Envia o preço e a quantidade atuais de cada produto (e variante) que tenha um SKU correspondente ao {sellerSku} do anúncio na Jumia. As atualizações são enviadas como feeds do Seller Center e aplicadas de forma assíncrona — o ID do feed fica registrado na aba Logs, e as rejeições por item aparecem na tela de status de feeds do Seller Center.',
'Jumia_Push_Prices_Stock' => 'Enviar preços e estoque',
'Jumia_Orders_Desc' => 'Importa pedidos do marketplace como vendas (referências como {ref}), associados aos seus produtos pelo Seller SKU. Pedidos já importados e cancelados são ignorados, então buscar com frequência é seguro. Os pagamentos são marcados como pagos apenas para pedidos entregues (a Jumia é predominantemente COD).',
'Jumia_Guide_1' => 'No {sellerCenter} da Jumia, abra Settings → {integrationMgmt} e gere uma chave de API.',
'Jumia_Guide_2' => 'Informe a URL da API do seu país (ex.: {ng} para a Nigéria, {ke} para o Quênia, {eg} para o Egito), o e-mail da sua conta do Seller Center e a chave — depois execute {test}.',
'Jumia_Guide_3' => 'Certifique-se de que o {sellerSku} de cada anúncio da Jumia seja igual ao código do produto no Stocky — essa é a identificação usada tanto no envio de estoque quanto na correspondência de pedidos.',
'Jumia_Guide_4' => 'Envie preços e estoque após alterações no inventário; importe pedidos regularmente (a Jumia não tem webhooks nesta API).',
'Jumia_Guide_5' => 'A criação de novos anúncios continua no Seller Center — a Jumia exige atributos específicos por categoria e revisão de imagens que só o portal deles trata bem.',
'Mc_Hero_Title' => 'Sincronização de público do Mailchimp',
'Mc_Hero_Desc' => 'Mantenha um público do Mailchimp preenchido com seus clientes, para que você possa fazer campanhas de e-mail com sua base real de clientes.',
'Mc_Account_Audience' => 'Conta e público',
'Mc_Api_Key_Placeholder' => 'ex.: a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'Público',
'Mc_N_Members' => '({n} membros)',
'Mc_Load_Audiences_To_Pick' => 'Carregue os públicos para escolher um',
'Mc_Load_Audiences' => 'Carregar públicos',
'Mc_Double_Opt_In_Label' => 'Double opt-in — novos membros recebem um e-mail de confirmação antes de entrar',
'Mc_Recommended_GDPR' => '(recomendado para a GDPR)',
'Mc_Auto_Sync_New' => 'Sincronizar automaticamente novos clientes assim que forem criados',
'Mc_With_Email' => 'Com e-mail',
'Mc_Push_Desc' => 'Insere ou atualiza no público selecionado todos os clientes que têm endereço de e-mail (incluindo nome e telefone). Os membros existentes mantêm seu status de inscrição — ninguém que cancelou a inscrição é reinscrito. Clientes sem e-mail ficam de fora.',
'Mc_Double_Opt_In_Off' => 'O double opt-in está desativado',
'Mc_Double_Opt_In_Off_Desc' => 'Novos membros serão adicionados como inscritos sem e-mail de confirmação. Faça isso apenas para clientes que já concordaram em receber marketing.',
'Mc_Guide_1' => 'No Mailchimp, abra {path} e crie uma chave (ela termina em {suffix} — esse sufixo é o seu datacenter).',
'Mc_Guide_2' => 'Cole a chave aqui, salve, depois clique em {load} e escolha o público a ser preenchido.',
'Mc_Guide_3' => 'Deixe o {doi} ativado, a menos que seus clientes já tenham consentido em receber e-mails de marketing.',
'Mc_Double_Opt_In_Lower' => 'double opt-in',
'Mc_Guide_4' => 'Execute {push} para o preenchimento inicial; ative a {autoSync} para que novos clientes entrem automaticamente.',
'Mc_Auto_Sync_Lower' => 'sincronização automática',
'Mc_Consent_Matters' => 'O consentimento importa',
'Mc_Consent_Desc' => 'Enviar e-mails a pessoas que nunca concordaram em receber marketing pode violar a GDPR/CAN-SPAM e levar à suspensão da sua conta do Mailchimp. O double opt-in transfere a confirmação para o Mailchimp — o padrão seguro.',
'Mc_No_Audiences' => 'Nenhum público encontrado nesta conta.',
'Presta_Hero_Desc' => 'Sincronize produtos, estoque e pedidos com sua loja PrestaShop por meio da API de webservice.',
'Presta_Webservice_Key' => 'Chave do webservice',
'Presta_Key_Placeholder' => 'Em Advanced Parameters → Webservice',
'Presta_Key_Help' => 'Ative o webservice no PrestaShop (Advanced Parameters → Webservice), crie uma chave com permissões em products, stock_availables, orders e customers e cole-a aqui. Armazenada somente para escrita.',
'Presta_Shop_Language_ID' => 'ID do idioma da loja',
'Presta_Language_Help' => 'ID do idioma usado nos nomes dos produtos ao enviar (1 = o primeiro idioma da loja).',
'Presta_Push_Desc' => 'Cria no PrestaShop os produtos simples que estiverem faltando (com o estoque atual). Produtos já vinculados e produtos com variantes são ignorados — continue editando os detalhes dos produtos no PrestaShop, ou importe para atualizar a cópia local.',
'Presta_Pull_Desc' => 'Importa os produtos do PrestaShop, fazendo a correspondência com os existentes pela referência (SKU) e criando os demais. As combinações são importadas como o respectivo produto pai.',
'Presta_Reset_Confirm' => 'Redefinir os vínculos de produtos? O histórico de pedidos mantém seus vínculos.',
'Presta_Stock_Desc' => 'Atualiza o estoque da loja (stock_availables) de todos os produtos vinculados.',
'Presta_Orders_Desc' => 'Importa os pedidos da loja como vendas (referências como {ref}), dos mais recentes para os mais antigos. Pedidos já importados e cancelados são ignorados, então é seguro importar com frequência. O PrestaShop não tem webhooks — execute isto após períodos de movimento intenso.',
'Presta_Guide_1' => 'No back office do PrestaShop, abra {path} e ative o webservice.',
'Presta_Guide_2' => 'Adicione uma nova chave, concedendo {vae} em {products} e {stock}, e {view} em {orders} e {customers}.',
'Presta_Guide_3' => 'Cole a URL da loja e a chave na aba Conexão, salve e execute {test}.',
'Presta_Guide_4' => 'Importe os produtos primeiro se a loja já tiver um catálogo (correspondência por referência/SKU); envie para criar os produtos simples que estiverem faltando.',
'Presta_Guide_5' => 'Envie o estoque sempre que as quantidades mudarem e importe pedidos regularmente — o PrestaShop não tem webhooks, então os pedidos só chegam quando você importa.',
'Presta_Identity_Title' => 'A identificação do produto é a referência (SKU)',
'Presta_Identity_Desc' => 'O código do produto no Stocky é comparado com a referência do PrestaShop. Mantenha as referências iguais nos dois lados; as combinações (variantes) são identificadas nos pedidos pela referência, mas não são enviadas nesta versão.',
'Gs_Hero_Title' => 'Exportações para o Google Sheets',
'Gs_Hero_Desc' => 'Exporte suas vendas, produtos e clientes para uma planilha Google ativa — uma aba para cada, atualizada sob demanda.',
'Gs_OAuth_Credentials' => 'Credenciais OAuth do Google',
