'Gs_Redirect_Uri_Title' => 'URI de redirecionamento para o cliente OAuth do Google',
'Gs_Export_Desc' => 'Cada exportação reescreve sua aba do zero (cabeçalho + todas as linhas), então a planilha é sempre um retrato completo e atual. Grandes volumes de dados são enviados em lotes — deixe a página aberta até o contador parar.',
