'Gs_Export_Products' => 'Exportar produtos',
'Gs_Export_Customers' => 'Exportar clientes',
'Gs_Job_Sales_Desc' => 'Todas as vendas com cliente, totais, status de pagamento e armazém.',
'Gs_Job_Products_Desc' => 'O catálogo completo com preços, custos e quantidades atuais em estoque.',
'Gs_Job_Customers_Desc' => 'Todos os clientes com seus dados de contato.',
'Gs_Guide_1' => 'Crie um projeto no {console} e ative a {api} (APIs & Services → Library).',
'Gs_Guide_2' => 'Configure a {consent} (External). Enquanto ela estiver em "Testing", adicione sua conta Google como usuário de teste — observe que os tokens de atualização no modo de teste expiram após 7 dias, então {publish} o app para ter uma conexão permanente.',
'Gs_OAuth_Consent_Screen' => 'tela de consentimento OAuth',
'Gs_Publish' => 'publique',
'Gs_Guide_3' => 'Crie um {clientId} do tipo Web application e registre o URI de redirecionamento exibido na aba Conexão.',
'Gs_OAuth_Client_ID' => 'ID do cliente OAuth',
'Gs_Guide_4' => 'Cole o Client ID e o Secret aqui, salve e clique em {connect}.',
'Gs_Guide_5' => 'Crie uma planilha com o botão (ou cole a URL de uma que sua conta Google possa editar) e depois execute as exportações.',
'Gs_Snapshots_Title' => 'Retratos, não sincronização em tempo real',
'Gs_Snapshots_Desc' => 'As exportações reescrevem as abas Vendas / Produtos / Clientes sob demanda. Para atualizações linha a linha em tempo real a cada venda, conecte o Zapier — ele pode adicionar linhas no momento em que os eventos ocorrem.',
