'Xero_Push_Customers_Desc' => 'Cria ou atualiza um contato no Xero para cada cliente. Um cliente cujo nome já existe no Xero é vinculado a esse contato.',
'Xero_Push_Sales_As_Invoices' => 'Enviar vendas como faturas',
'Xero_Push_Invoices_Desc' => 'Cria uma fatura AUTHORISED por venda (número da fatura = a Ref. da venda), com os itens da venda mais as linhas de frete, desconto e imposto, para que o total no Xero corresponda ao total da venda. Vendas que já estão no Xero são ignoradas — as faturas nunca são editadas. Contatos ausentes são criados na hora.',
'Xero_Push_Invoices' => 'Enviar faturas',
'Xero_Reset_Contact_Confirm' => 'Redefinir os vínculos de contatos? O próximo envio os vincula novamente ou os recria.',
