'Xero_Guide_4' => 'Clique em {connect}, faça login e escolha a organização a ser conectada.',
'Xero_Guide_5' => 'Verifique os códigos de conta: a conta de vendas recebe as linhas da fatura; defina um código de conta bancária se as vendas pagas também devem registrar pagamentos.',
'Xero_Guide_6' => 'Envie primeiro os clientes, depois as faturas. Os números das faturas são as Refs. das vendas, então o Xero rejeita duplicatas mesmo que os vínculos sejam redefinidos.',
'Xero_Tax_Inclusive_Title' => 'Os valores são enviados com impostos incluídos, como estão',
'Xero_Tax_Inclusive_Desc' => 'As faturas usam linhas NoTax que refletem a venda exatamente (itens + frete − desconto + imposto), então os totais do Xero sempre são iguais aos totais do Stocky. Seu contador pode remapear as linhas de imposto e frete para as contas adequadas dentro do Xero.',
'Xero_Org_Connected' => 'Organização do Xero conectada.',
