'Salla_Variants_Linked' => 'Variantes vinculadas',
'Salla_Push_Desc' => 'Cria ou atualiza produtos simples na Salla pelo SKU. Produtos com variantes são ignorados nesta versão — importe-os da Salla ou faça a correspondência pelo SKU.',
'Salla_Only_Unlinked' => 'Somente produtos ainda não vinculados',
