'Salla_Reset_Confirm' => 'Redefinir os vínculos de produtos e variantes? O histórico de pedidos mantém seus vínculos.',
'Salla_Stock_Desc' => 'Envia as quantidades atuais de todos os produtos vinculados (pelo SKU) e variantes vinculadas.',
'Salla_Orders_Desc' => 'Os novos pedidos da Salla normalmente chegam sozinhos pelos webhooks e se tornam vendas. Use esta importação para recuperar pedidos feitos antes de o webhook ser configurado — pedidos já importados são ignorados.',
'Salla_Guide_1' => 'Crie um app (privado) em {link} e escolha o fluxo de autorização {mode}.',
