'Fbr_Guide_What_Title' => 'O que é o FBR Digital Invoicing?',
'Fbr_Guide_What_Body' => 'De acordo com a SRO 69(I)/2025, o Federal Board of Revenue (Paquistão) exige que as empresas integradas informem as faturas de venda eletronicamente, em tempo real, por meio da API PRAL Digital Invoicing (DI). Cada venda aceita recebe um número de fatura FBR oficial, e os recibos devem exibir esse número junto com um QR code de verificação.',
'Fbr_Guide_Steps_Title' => 'Etapas para entrar em produção',
'Fbr_Guide_Step_1' => 'Cadastre-se no portal de faturamento eletrônico FBR IRIS e obtenha um token de segurança de {sandbox}.',
'Fbr_Guide_Step_2' => 'Configure seu perfil de vendedor na aba Configuração (NTN/CNIC, nome da empresa, província, endereço), cole o token e ative a integração com o ambiente definido como {sandbox}.',
'Fbr_Guide_Step_3' => 'Faça vendas de teste cobrindo o(s) cenário(s) que o FBR atribuiu a você (escolha o cenário no campo Cenário de sandbox). Confira a aba Documentos para confirmar que elas retornam como {valid}.',
'Fbr_Guide_Step_4' => 'Quando o FBR aprovar seus testes no sandbox, obtenha o token de {production} no portal, cole-o aqui e mude o ambiente para {production}.',
'Fbr_Guide_Step_5' => 'Os recibos mostram automaticamente o número de fatura FBR e o QR code assim que uma venda é aceita — nenhuma etapa extra é necessária no ponto de venda.',
'Fbr_Sandbox_Lower' => 'sandbox',
'Fbr_Production_Lower' => 'produção',
'Fbr_Guide_Note_1' => 'Defina os códigos HS por produto no formulário do produto (campo "Código HS"). O Código HS padrão configurado aqui é usado apenas para produtos sem código.',
'Fbr_Guide_Note_2' => 'Clientes avulsos não registrados são reportados ao FBR como "Unregistered".',
'Fbr_Guide_Note_3' => 'Compradores registrados precisam ter o NTN informado no campo Número fiscal do cliente para serem reportados como registrados.',
'Fbr_Guide_Note_4' => 'Envios com falha ou inválidos podem ser reenviados pela aba Documentos depois de corrigir a causa; a aba Logs mostra as trocas brutas com a API para diagnóstico.',
