'Woo_WordPress_Username' => 'Usuário do WordPress',
'Woo_WordPress_App_Password' => 'Senha de aplicativo do WordPress',
'Woo_Automatic_Sync' => 'Sincronização automática',
'Woo_Auto_Sync_Intro' => 'Envie as alterações feitas no Stocky para o WooCommerce assim que acontecem, sem abrir esta página. Cada envio é executado logo após a ação ser salva, então o caixa nunca espera pelo WooCommerce. Os resultados aparecem na aba Logs.',
'Woo_Auto_Sync_Products_Help' => 'Um produto criado, editado ou duplicado no Stocky é enviado ao WooCommerce (detalhes, preço, variantes, imagens, estoque). Importações em massa não são enviadas; após uma importação, use Sincronizar — POS → WooCommerce na aba Produtos.',
'Woo_Auto_Sync_Stock_Help' => 'Qualquer movimentação de estoque (venda no PDV, venda, devolução, compra, ajuste, transferência) atualiza a quantidade dos produtos envolvidos no WooCommerce. Somente produtos já vinculados ao WooCommerce são atualizados.',
'Woo_Sync_Tuning' => 'Ajuste fino da sincronização',
'Woo_Sync_Tuning_Intro' => 'Os valores padrão atendem à maioria das lojas. Altere-os apenas se a sincronização estiver lenta ou expirar na sua hospedagem. Cada valor é limitado a uma faixa segura, e limpar um campo restaura o padrão.',
'Woo_Sync_Guide' => 'Guia de sincronização do WooCommerce',
'Woo_Guide_Getting_Keys' => 'Obtendo as chaves de API',
'Woo_Guide_Keys_1' => 'No WooCommerce: WooCommerce → Settings → Advanced → REST API.',
'Woo_Guide_Keys_2' => 'Clique em "Add key", escolha Read/Write e copie a Consumer key e o Consumer secret.',
'Woo_Guide_Keys_3' => 'URL da Loja: a URL do seu site sem barra no final (ex.: {example}).',
'Woo_Guide_WP_Title' => 'Usuário do WP e senha de aplicativo (opcional)',
'Woo_Guide_WP_Intro' => 'Estes campos são usados apenas para imagens de produtos. A API do WooCommerce (URL da Loja + chave/segredo do consumidor) cuida da sincronização de produtos, estoque, categorias, marcas, clientes e pedidos; a API REST do WordPress cuida da Biblioteca de Mídia (busca e envio de imagens).',
'Woo_Guide_WP_1' => 'Ao sincronizar produtos ou estoque, o Stocky pode anexar imagens aos produtos: primeiro ele procura na Biblioteca de Mídia do WordPress uma imagem existente pelo nome do arquivo; se não encontrar, envia a imagem pela API do WordPress.',
'Woo_Guide_WP_2' => 'Use um usuário do WordPress que possa gerenciar mídia (ex.: Administrador). Crie uma senha de aplicativo no WordPress: Users → Profile (ou seu usuário) → Application Passwords — adicione uma nova e cole-a aqui.',
'Woo_Guide_WP_3' => 'Se você deixar estes campos em branco, a sincronização continua funcionando para todos os dados (produtos, estoque, categorias, marcas, clientes, pedidos); apenas o anexo de imagens aos produtos (busca/envio) é ignorado.',
'Woo_Guide_How_To_Enable' => 'Como ativar',
'Woo_Guide_Enable_1' => 'Informe a URL da Loja, a Chave do Consumidor e o Segredo do Consumidor acima e clique em Salvar.',
'Woo_Guide_Enable_2' => 'Use Testar Conexão para verificar as credenciais.',
'Woo_Guide_Enable_3' => 'Use a sincronização manual em qualquer aba quando precisar sincronizar.',
'Woo_Guide_Enable_4' => 'Ative a Sincronização automática acima para enviar produtos novos e editados e cada alteração de estoque ao WooCommerce assim que acontecem.',
'Woo_Guide_Manual_Sync' => 'Sincronização manual (sob demanda)',
'Woo_Guide_Manual_1' => 'A sincronização funciona nas duas direções: Stocky → WooCommerce e WooCommerce → Stocky.',
'Woo_Guide_Manual_2' => 'A sincronização manual está disponível em todas as abas do WooCommerce (Produtos, Estoque etc.); use as ações de sincronização de cada aba para sincronizar sob demanda.',
'Woo_Guide_Auto_1' => 'Produtos: quando ativado, um produto que você cria, edita ou duplica no Stocky é enviado ao WooCommerce logo após ser salvo, seguido do seu estoque.',
'Woo_Guide_Auto_2' => 'Estoque: quando ativado, cada alteração de estoque (venda no PDV, venda, devolução, compra, ajuste, transferência) atualiza a quantidade no WooCommerce. Somente produtos já vinculados ao WooCommerce são atualizados.',
'Woo_Guide_Auto_3' => 'A sincronização automática envia alterações apenas do Stocky para o WooCommerce. Trazer dados do WooCommerce para o Stocky (pedidos, clientes, produtos) é sempre feito pelos botões das abas Pedidos, Clientes e Produtos.',
'Woo_Guide_Auto_4' => 'Importações de produtos em massa não são enviadas automaticamente. Após uma importação, use Sincronizar — POS → WooCommerce na aba Produtos.',
'Woo_Guide_Auto_5' => 'Cada envio automático é registrado na aba Logs, para que você possa conferir o que foi enviado e identificar erros.',
'Woo_Guide_First_Setup' => 'Primeira configuração',
'Woo_Guide_First_1' => 'Execute estes passos uma vez, nesta ordem, para que seu catálogo existente seja vinculado: Sincronizar — POS → WooCommerce na aba Categorias, depois na aba Marca, depois na aba Produtos e, por fim, Sincronizar Estoque na aba Estoque. Depois disso, ative a Sincronização automática acima para manter o WooCommerce atualizado.',
'Woo_Guide_First_2' => 'Sincronizações grandes de produtos e estoque são executadas em pequenos lotes e mostram o progresso na aba. Mantenha a página aberta até a sincronização terminar; você pode interrompê-la a qualquer momento.',
'Woo_Guide_First_3' => 'Se uma sincronização parar de avançar por vários minutos, verifique a aba Logs e entre em contato com o suporte.',
'Woo_Guide_Notes_1' => 'Alterar a URL da Loja ou as chaves de API redefine os mapeamentos (produtos, categorias, marcas, clientes); os itens serão sincronizados novamente com a (nova) loja.',
'Woo_Guide_Notes_2' => 'Mantenha os SKUs consistentes entre o Stocky e o WooCommerce para evitar produtos duplicados e para revincular com segurança.',
