'Pg_Store_Feature_Not_In_Plan' => 'Os gateways da loja online e as formas de pagamento offline fazem parte do recurso Pedidos online, que não está incluído no seu plano atual.',
'Pg_Intro_Title' => 'Cada gateway aqui é oferecido no checkout da LOJA ONLINE assim que suas credenciais forem salvas e sua opção estiver ativada.',
'Pg_Intro_Desc' => 'Cada aba tem sua própria chave liga/desliga, salva no momento em que você a aciona: desativar um gateway mantém suas credenciais, o checkout simplesmente deixa de oferecê-lo. As chaves do Stripe são compartilhadas globalmente (o admin e a loja online usam a mesma integração Stripe). Pagamentos offline reúne pagamento na entrega e dinheiro móvel, que são pagos fora do sistema.',
