'Pg_Paymob_Help' => 'Usa o Paymob Unified Checkout (cartões, carteiras e métodos locais no Egito, Arábia Saudita, Emirados Árabes Unidos, Paquistão e Omã). As cinco credenciais vêm de Paymob Dashboard → Settings → Account Info + Payment Integrations.',
'Pg_Paymob_Webhook_Help' => 'O webhook é configurado automaticamente a cada pagamento — nenhuma configuração no painel é necessária. URL de callback de respaldo para referência:',
