'Pg_Myfatoorah_Country_Help' => 'Código ISO do país da sua conta MyFatoorah — KWT, SAU, QAT, EGY, ARE, BHR, OMN ou JOR. Seleciona o host da API de produção; ignorado no modo sandbox.',
'Pg_Myfatoorah_Currency_Help' => 'Deve corresponder à moeda da sua conta MyFatoorah (KWD, SAR, AED, QAR, BHD, OMR, JOD, EGP…) e à moeda base da sua loja.',
'Pg_Myfatoorah_Sandbox_Help' => 'ATIVADO usa apitest.myfatoorah.com com um token de API de demonstração; DESATIVE para cobrar clientes reais na API de produção.',
'Pg_Myfatoorah_Help' => 'Link de fatura hospedado que abrange KNET, mada, cartões, Apple Pay e STC Pay em todo o GCC. O token de API vem de MyFatoorah Vendor Portal → Integration Settings → API Key.',
