'Pg_Xpay_Help' => 'Os cartões são digitados em um elemento XPay incorporado à página de checkout (sem redirecionamento). Cada pagamento é verificado novamente no servidor antes de o pedido ser criado. Observação: o SDK da XPay exige o segredo HMAC da API no navegador, assim como nos plugins oficiais da XPay.',
