'Shp_Create_Missing_Customers' => 'Criar clientes no ERP para clientes do Shopify que não correspondem a um e-mail',
'Shp_Create_Missing_Customers_Hint' => 'Com isto desativado, um pedido de um cliente desconhecido é ignorado em vez de ser adivinhado.',
'Shp_Entities_Lead' => 'Somente as entidades ativadas aqui podem ser sincronizadas — uma loja da qual você apenas importa pedidos não deve ter um envio de produtos acidental reescrevendo seu catálogo.',
'Shp_Sync_On_Schedule' => 'Sincronizar automaticamente por agendamento',
'Shp_Scheduler_Hint' => 'O agendador verifica a cada 5 minutos, que é a menor resolução que os intervalos abaixo podem usar. As sincronizações sempre podem ser iniciadas manualmente.',
'Shp_Instant_Push_Hint' => 'Uma venda, devolução ou ajuste envia o estoque apenas desses produtos no instante em que é salvo, para que a loja fique correta em segundos em vez de na próxima execução agendada. Nada mais para instalar — o envio é executado depois que a venda foi respondida, então o caixa nunca espera pelo Shopify.',
'Shp_Switch_Inventory_First' => 'Ative primeiro o Inventário em {tab}.',
'Shp_Leave_Off_Lag' => 'Se ficar desativado, uma venda no PDV só chega ao Shopify no próximo envio de Inventário — até {n} minutos depois.',
'Shp_Default_Interval' => 'Intervalo padrão (minutos)',
'Shp_Default_Interval_Hint' => 'Usado por todas as etapas que não definem o próprio intervalo.',
'Shp_What_Runs_Auto' => 'O que é executado automaticamente',
'Shp_Plan_Hint' => 'Cada etapa é uma entidade em uma direção. Os pedidos sempre vêm {from} Shopify.',
'Shp_From' => 'do',
'Shp_Add_Step' => 'Adicionar etapa',
'Shp_Using_Default_Plan' => 'Usando o plano padrão',
'Shp_Default_Plan_Desc' => 'Os pedidos são importados e o estoque é enviado a cada {n} minutos. Adicione uma etapa para escolher o seu próprio — limpar a lista novamente restaura este padrão.',
'Shp_N_Min' => '{n} min',
'Shp_Step_Entity_Off' => '{entity} está desativado na aba anterior — esta etapa será ignorada.',
'Shp_Inactive_Lc' => 'inativo',
'Shp_No_Locations' => 'Essa loja não informa nenhum local',
'Shp_Could_Not_Load_Locations' => 'Não foi possível carregar os locais — verifique a conexão primeiro',
'Shp_Store_Updated' => 'Loja atualizada',
'Shp_Store_Connected' => 'Loja conectada',
'Shp_Could_Not_Save_Store' => 'Não foi possível salvar esta loja',
'Shp_G_Lead_Store' => 'O que esta loja precisa para se manter sincronizada. Tudo aqui é específico desta loja — a URL do webhook e os IDs são reais.',
'Shp_G_Lead_Store_Cmd' => 'O que esta loja precisa para se manter sincronizada. Tudo aqui é específico desta loja — a URL do webhook e os IDs são reais, então os comandos podem ser copiados direto para o servidor.',
'Shp_G_Lead_Generic' => 'Como uma loja Shopify se mantém sincronizada com o ERP. Escolha uma loja acima para ver o estado dela, ou leia como está — a URL do webhook é a mesma para qualquer loja que você conectar.',
'Shp_G_Lead_Generic_Cron' => 'Como uma loja Shopify se mantém sincronizada com o ERP. Escolha uma loja acima para ver o estado dela, ou leia como está — a URL do webhook e a linha do cron são as mesmas para qualquer loja que você conectar.',
'Shp_G_Ways_Note' => 'A maioria das lojas usa as duas: a primeira mantém a loja atualizada minuto a minuto, a segunda pega o que a primeira deixou passar — um webhook que nunca chegou, uma edição feita direto no admin do Shopify, uma noite em que o site ficou fora do ar.',
'Shp_G_Both_Need' => 'As duas formas precisam disto primeiro',
'Shp_G_Credentials' => 'Credenciais do Shopify',
'Shp_G_Cred_Intro' => 'Desde janeiro de 2026, o Shopify não cria mais apps personalizados dentro do admin, então há dois tipos de conexão:',
'Shp_G_Cred_Dev' => '{app} (qualquer loja conectada agora) — {path}. Conceda os escopos da Admin API para o que esta loja sincroniza, instale o app na loja e copie o {clientId} e o {clientSecret} da página Settings do app para {edit}. O ERP os troca sozinho por um token de acesso e o renova antes de expirar, a cada 24 horas. O segredo do cliente também assina os webhooks, então nada mais é necessário. O app e a loja devem estar na mesma organização Shopify.',
'Shp_G_Dev_App' => 'App do Dev Dashboard',
'Shp_G_Cred_Legacy' => '{app} (criado no admin antes de 2026) — continua funcionando sem alterações com seu {token} ({prefix}) e sua {secret} como segredo de assinatura do webhook. Não é o mesmo valor que o token, e trocar um pelo outro é o motivo mais comum de webhooks recusados.',
'Shp_G_Legacy_App' => 'App personalizado legado',
'Shp_G_Api_Secret_Key' => 'Chave secreta da API',
'Shp_G_Stored' => 'salvo',
'Shp_G_Missing_Refused' => 'ausente — as entregas serão recusadas',
'Shp_G_Targets' => '{path} O armazém do ERP cujo estoque esta loja vende e o local do Shopify onde esse estoque é gravado. A sincronização de inventário e a importação de pedidos se recusam a rodar sem eles.',
'Shp_G_Currently' => 'Atualmente: armazém {warehouse}, local {location}',
'Shp_G_Not_Set_Lc' => 'não definido',
'Shp_G_Ready' => 'pronto',
'Shp_G_Incomplete' => 'incompleto',
'Shp_G_Manual_Syncs' => 'Sincronizações iniciadas manualmente',
'Shp_G_Manual_Body' => 'Uma sincronização iniciada pela {centre} responde na hora e roda em segundo plano, em pequenas partes que continuam de onde a anterior parou. Um catálogo grande nunca é interrompido no meio por uma requisição web que esgota o tempo, e fechar a página não a interrompe.',
'Shp_G_Worker_Managed' => 'Sua plataforma executa o worker para isso, então não há nada para instalar.',
'Shp_G_Worker_Cron' => 'O worker para isso é mais uma linha do cron:',
'Shp_G_Cron_Copied' => 'Linha do cron copiada',
'Shp_G_Worker_Busy' => 'Se o worker estiver ocupado, a página aberta da Central de Sincronização continua a execução sozinha após alguns segundos, uma requisição curta por vez — assim uma sincronização sempre termina enquanto você acompanha.',
'Shp_G_Pick_How' => 'Depois escolha como ela se mantém sincronizada',
'Shp_G_Right_Away' => 'Imediatamente',
'Shp_G_Stock_Live' => 'estoque em tempo real',
'Shp_G_Stock_Not_Live' => 'estoque não está em tempo real',
'Shp_G_Realtime_Lead' => 'Cada alteração é enviada assim que acontece, em segundos. São duas metades, com opções separadas: os {webhooks} trazem os eventos da própria loja, e o {push} envia o estoque.',
'Shp_G_Webhooks_Lc' => 'webhooks',
'Shp_G_Instant_Push_Lc' => 'envio instantâneo de estoque',
'Shp_G_Webhooks_Heading' => 'Webhooks — a loja → o ERP',
'Shp_G_Webhooks_Body' => 'Pedidos, mudanças de status de pedidos e edições de produtos, clientes e estoque feitas no Shopify. Abra a loja e clique em {button} na {tab} — é seguro clicar duas vezes. O Shopify envia para:',
'Shp_G_Webhooks_Tab' => 'aba Webhooks',
'Shp_G_Webhooks_Note' => 'O endereço precisa estar acessível pela internet via HTTPS — o Shopify não entrega para {localhost} nem para um domínio {test}. Cada entrega é registrada uma única vez, então as novas tentativas do Shopify não podem criar um pedido duplicado, e uma entrega com falha pode ser reprocessada. As entregas são recusadas até que o segredo de assinatura do passo 1 seja salvo.',
'Shp_G_Push_Heading' => 'Envio instantâneo de estoque — o ERP → a loja',
'Shp_G_People_Miss' => 'Esta é a configuração que as pessoas esquecem',
'Shp_G_Push_P1' => 'Uma venda no PDV {not} chega ao Shopify sozinha. Se ficar desativado, a loja só fica sabendo na próxima etapa de envio de Inventário — e, nesse intervalo, pode vender uma unidade que você já vendeu no caixa.',
'Shp_G_Not' => 'não',
'Shp_G_Push_P2' => 'Marque {setting} em {path}. Essa é toda a configuração — sem worker, sem cron. Cada venda, devolução e ajuste passa a enviar apenas esses produtos, logo após a venda ser salva, e uma venda de vinte linhas custa um envio, não vinte. O caixa nunca espera por isso.',
'Shp_G_This_Store' => 'Esta loja:',
'Shp_G_Push_On' => 'ativado — estoque enviado ao mudar',
'Shp_G_Push_Off' => 'desativado — estoque apenas pelo agendamento',
'Shp_G_Push_Note' => 'Somente produtos que já têm um mapeamento no Shopify, e somente movimentações no armazém desta loja, são enviados. Operações em massa — excluir um produto, redefinir um armazém — gravam o estoque sem disparar um evento, o que é um motivo para manter também a etapa agendada de inventário.',
'Shp_G_Nothing_Else' => 'Nada mais para instalar',
'Shp_G_Nothing_Else_Body' => 'Nenhuma das metades precisa de um worker de fila ou de uma entrada no cron. Um webhook recebido é tratado na própria requisição que o Shopify faz; um envio de estoque roda no mesmo processo que atendeu a venda, {after} que a resposta foi devolvida — então o caixa nunca fica esperando pelo Shopify, e uma loja que para de responder é abandonada após dez segundos e fica para o próximo envio agendado de inventário.',
'Shp_G_After' => 'depois',
'Shp_G_Exception' => 'Uma exceção: uma alteração de estoque feita por uma tarefa em segundo plano não tem resposta para esperar, então ela é enfileirada em {queue}.',
'Shp_G_Queue_Managed' => 'Sua plataforma já executa um worker nessa fila, então esses envios também saem sozinhos.',
'Shp_G_Queue_Cron' => 'Se você quiser que esses envios também saiam rapidamente, processe essa fila:',
'Shp_G_On_Schedule' => 'Por agendamento',
'Shp_G_On_Lc' => 'ativado',
'Shp_G_Off_Lc' => 'desativado',
'Shp_G_Scheduled_Lead' => 'Tudo é verificado novamente de tempos em tempos, nas duas direções. É mais lento que o tempo real, mas é o que envia o estoque nas lojas que não usam o envio instantâneo, o que pega um webhook perdido e a única forma de movimentar um catálogo inteiro.',
'Shp_G_Nothing_To_Install' => 'Nada para instalar',
'Shp_G_Managed_Body' => 'O agendador é executado para você: a cada cinco minutos sua plataforma pergunta a cada loja se alguma etapa do plano está pendente e executa as que estiverem. Não há entrada de cron para adicionar nem servidor para manter.',
'Shp_G_Managed_Note' => 'Cinco minutos também é a menor resolução que um plano pode usar, porque cinco minutos é o menor intervalo de etapa. Intervalos maiores são respeitados exatamente — uma etapa definida para 30 minutos é verificada seis vezes e executada uma vez.',
'Shp_G_Cron_Entry' => 'A entrada do cron',
'Shp_G_Cron_Body' => 'Nada agendado é executado sem ela. Uma linha, apenas para este módulo — adicione-a junto com o que mais você tiver agendado:',
'Shp_G_Cron_Note' => 'A cada cinco minutos é a menor resolução que um plano pode usar, porque cinco minutos é o menor intervalo de etapa. Uma entrada menos frequente simplesmente vira o mínimo — com {every15}, uma etapa definida para 5 minutos roda a cada 15. No Windows, use o Agendador de Tarefas: programa {php}, argumentos {args}, iniciar em {path}.',
'Shp_G_Switch_On' => 'Ative e escolha o plano',
'Shp_G_Plan_Body' => '{path} A opção decide se o agendador pode agir; o plano decide o que ele faz. Uma {step} é uma entidade em uma direção com seu próprio intervalo — {ex1}, {ex2}. O intervalo padrão é usado por qualquer etapa que deixe seu campo vazio.',
'Shp_G_Step_Lc' => 'etapa',
'Shp_G_Ex1' => 'Pedidos · Shopify → ERP a cada 15 min',
'Shp_G_Ex2' => 'Inventário · ERP → Shopify a cada 30 min',
'Shp_G_Plan_Note' => 'Deixe o plano vazio e a loja importa pedidos e envia estoque no intervalo padrão, que é o que a maioria das lojas quer. Pedidos são apenas importados: é no Shopify que o cliente faz o pedido.',
'Shp_G_Schedule_On' => 'agendamento ativado',
'Shp_G_Schedule_Off' => 'agendamento desativado — somente manual',
'Shp_G_When_Runs' => 'Quando uma etapa realmente é executada',
'Shp_G_When_Body' => 'Uma etapa fica pendente quando a última vez que essa mesma etapa {started} foi há mais tempo que seu intervalo, conforme o histórico de execuções. Assim, uma sincronização iniciada manualmente adia a próxima automática, e uma etapa que continua falhando é tentada novamente no seu intervalo, e não a cada verificação. A Visão geral da loja mostra a última execução de cada etapa, o próximo horário previsto e o motivo do bloqueio, quando houver. Faça o primeiro envio de catálogo manualmente pela Central de Sincronização — primeiro como simulação — antes de colocá-lo em agendamento.',
'Shp_G_Started_Lc' => 'iniciou',
'Shp_G_Where_Setting' => 'Onde fica cada configuração',
'Shp_G_Where_Note' => 'Todas ficam em uma loja existente: {path}, depois o lápis (ou {edit} na própria página da loja).',
'Shp_G_Product_Images' => 'Imagens dos produtos',
'Shp_G_Img1' => 'As imagens vão junto com o produto em um {push} — primeiro a imagem principal, depois a galeria, depois uma por variante que tenha a sua própria, até cinquenta.',
'Shp_G_Products_Push' => 'envio de produtos',
'Shp_G_Img2' => 'A imagem de uma variante é enviada com o produto e depois {assigned}, que é como o Shopify modela isso: uma variante aponta para uma das imagens do produto. Uma variante que reutiliza a imagem principal não a envia duas vezes.',
'Shp_G_Assigned' => 'atribuída a essa variante',
'Shp_G_Img3' => 'Uma imagem armazenada como arquivo é {uploaded} ao Shopify, não vinculada, então funciona mesmo quando esta instalação não está acessível pela internet. Uma imagem adicionada como link colado é passada ao Shopify como essa URL, que precisa ser publicamente acessível.',
'Shp_G_Uploaded' => 'enviada',
'Shp_G_Img4' => 'Elas só são reenviadas quando realmente mudam — um envio que altera apenas um preço não mexe nas imagens da loja, porque enviá-las substitui o conjunto inteiro.',
'Shp_G_Img5' => 'Remover uma imagem no ERP {not} a exclui no Shopify. Exclua-a lá também, ou a loja continuará exibindo-a.',
'Shp_G_Commands' => 'Comandos úteis',
'Shp_G_Command_Copied' => 'Comando copiado',
'Shp_G_Foot' => 'Cada sincronização grava em {logs}, e a Visão geral de cada loja mostra quando cada etapa foi executada pela última vez, quando é a próxima e o que a está bloqueando, se houver algo. É ali que você deve olhar primeiro quando uma sincronização não fez o que você esperava.',
'Shp_G_Covers' => 'Abrange',
'Shp_G_Speed' => 'Velocidade',
'Shp_G_Needs' => 'Requisitos',
'Shp_G_Switched_On_At' => 'Ativado em',
'Shp_G_Way_Covers_Rt' => 'Pedidos e edições feitos no Shopify; estoque saindo do ERP (uma venda no PDV, uma devolução, um ajuste)',
'Shp_G_Way_Covers_Sc' => 'Tudo, nas duas direções — incluindo envios de catálogo e qualquer coisa que o caminho rápido deixou passar',
'Shp_G_Seconds' => 'Segundos',
'Shp_G_Way_Speed_Sc' => 'O intervalo da etapa (5 minutos a 7 dias)',
'Shp_G_Way_Needs_Rt' => 'Um endereço HTTPS público e o segredo de assinatura para os webhooks recebidos. O estoque enviado não precisa de nada',
'Shp_G_Way_Needs_Sc' => 'O agendador, a cada cinco minutos',
'Shp_G_Way_Switch_Sc' => '{path}, além do plano',
'Shp_G_Scope_Orders' => '{a} ({b} para pedidos com mais de 60 dias)',
'Shp_G_Admin_Scopes' => 'Escopos da Admin API',
'Shp_G_Setting' => 'Configuração',
'Shp_G_Tab_In_Edit' => 'Aba em Editar loja',
'Shp_G_Set1' => 'ID do cliente + segredo ou token de acesso, segredo de assinatura, versão da API',
'Shp_G_What1' => 'As credenciais do app Shopify (Dev Dashboard ou app personalizado legado).',
'Shp_G_Set2' => 'Armazém do ERP, local do Shopify',
'Shp_G_What2' => 'Qual estoque esta loja vende e onde os pedidos são registrados.',
'Shp_G_What3' => 'Preço de varejo, de atacado ou mínimo.',
