'Shp_G_Set8' => 'Intervalo padrão e o plano de etapas',
'Shp_G_What8' => 'O que roda sozinho, em qual direção e com que frequência.',
'Shp_G_Cmd1' => 'Todas as lojas: o que seria executado e quando. Não altera nada.',
