'Mk_WA_Template' => 'Modelo aprovado pela Meta',
'Mk_WA_Template_Help' => 'Necessário para alcançar clientes que não enviaram mensagem a você nas últimas 24 horas. Informe o modelo exatamente como foi aprovado no WhatsApp Manager. Deixe o nome vazio para enviar a mensagem abaixo como texto livre.',
