'Agt_Series' => 'Séries',
'Agt_Series_Hint' => 'A AGT autoriza uma série de numeração por tipo de documento, ano e estabelecimento. As faturas não podem ser emitidas sem uma série ativa para o tipo e o ano.',
'Agt_Request_Series' => 'Solicitar série à AGT',
