'Agt_Correct' => 'Corrigir',
'Agt_Guide_What_Title' => 'O que isto faz',
'Agt_Guide_What_Body' => 'Cada venda concluída é emitida como fatura eletrônica AGT (FR quando paga na criação, caso contrário FT) e cada devolução recebida como nota de crédito (NC). Cada documento recebe o próximo número da sua série AGT, é assinado com a sua chave AGT e enviado à AGT, que o valida alguns minutos depois. O recibo e a fatura em PDF imprimem o número AGT, o extrato de segurança e um QR code.',
'Agt_Guide_Steps_Title' => 'Configuração',
'Agt_Guide_Step_1' => 'Faça a adesão ao faturamento eletrônico no Portal do Contribuinte e baixe a sua chave privada AGT.',
'Agt_Guide_Step_2' => 'Informe seu NIF, estabelecimento e a chave na aba Configuração, escolha Homologação, salve e use Testar conexão.',
'Agt_Guide_Step_3' => 'Na aba Séries, solicite uma série para cada tipo de documento que você usa (FR, FT, NC) para o ano atual.',
'Agt_Guide_Step_4' => 'Mapeie suas taxas de IVA para os códigos AGT e defina o código de isenção para linhas a 0%.',
'Agt_Guide_Step_5' => 'Ative o módulo em Configurações do sistema > Recursos, faça uma venda de teste e verifique se ela fica válida na aba Documentos.',
'Agt_Guide_Step_6' => 'Quando a AGT aprovar você para produção, mude para Produção e solicite séries de produção.',
'Agt_Guide_Note_1' => 'Uma venda ou devolução comunicada não pode mais ser editada nem excluída. Corrija-a com uma devolução de venda (nota de crédito).',
'Agt_Guide_Note_2' => 'Documentos rejeitados pela AGT são corrigidos com um novo número que referencia o rejeitado; o número antigo nunca é reutilizado.',
'Agt_Guide_Note_3' => 'Vendas offline do PDV são comunicadas quando sincronizam. A AGT penaliza documentos enviados com mais de 24 horas de atraso.',
'Agt_Guide_Note_4' => 'Uma linha não pode ter ao mesmo tempo um imposto de produto e o imposto do pedido; a AGT exige uma taxa de IVA por linha. O frete é enviado como linha isenta.',
'Agt_Guide_Note_5' => 'Os totais da AGT são calculados por linha e podem diferir do total do Stocky em alguns centavos por arredondamento.',
