'Dgi_Api_Pending_Body' => 'A DGI publica a API de desenvolvedor do e-MCF apenas para desenvolvedores registrados (developper.dgirdc.cd). Até que ela seja conectada, as faturas trazem suas menções NIF / RCCM / Id. Nat., mas nenhum número DEF, código de autenticação ou QR.',
