'Dgi_Group' => 'Grupo',
'Dgi_No_Documents' => 'Nenhuma fatura certificada ainda — a certificação começa assim que a conexão e-MCF estiver ativa.',
'Dgi_Guide_What_Title' => 'O que isto faz hoje',
'Dgi_Guide_What_Body' => 'Com o módulo ativado, recibos e faturas em PDF imprimem o NIF, o RCCM e o Id. Nat. do vendedor exigidos na facture normalisée. A certificação completa (número DEF, contadores, código de autenticação e QR devolvidos pela DGI) será adicionada assim que a API de desenvolvedor do e-MCF for conectada.',
'Dgi_Guide_Steps_Title' => 'Obtendo acesso ao e-MCF',
'Dgi_Guide_Step_1' => 'Crie uma conta com seu NIF em developper.dgirdc.cd e solicite acesso ao ambiente de testes do e-MCF.',
'Dgi_Guide_Step_2' => 'Baixe a documentação da API (rotas, DTOs, grupos de tributação) e as credenciais de teste.',
'Dgi_Guide_Step_3' => 'Envie-as ao administrador da plataforma para que a conexão possa ser concluída e testada.',
