'Comm_G_Intro_Title' => 'Como as comissões funcionam, em uma frase',
'Comm_G_Intro' => 'Quando uma venda concluída é salva, as regras que correspondem ao representante de vendas da venda criam comissões Pendentes. Você as aprova no Relatório de Comissões e as paga com um Recibo de Comissão. Se a venda mudar depois (pagamentos, devoluções, edições, exclusão), as comissões dela são recalculadas automaticamente.',
'Comm_G_Your_Setup' => 'Sua configuração',
