'Comm_G_How_It_Works' => 'Como funciona',
'Comm_G_T_Credit' => 'Qual representante recebe a comissão?',
'Comm_G_Credit_Intro' => 'Cada venda é creditada a no máximo um representante. O sistema verifica, nesta ordem:',
'Comm_G_Credit_Picked' => 'O representante de vendas escolhido na venda: o campo Representante de vendas em Criar venda e Editar venda, ou o botão "Vendido por" no PDV. Se esse representante tiver sido desativado depois, a venda não gera nada; ela não passa para as próximas opções.',
'Comm_G_Credit_Seller' => 'Caso contrário, o representante vinculado ao vendedor escolhido no PDV (quando a opção de vendedor do PDV estiver ativada).',
'Comm_G_Credit_Cashier' => 'Caso contrário, o representante vinculado ao usuário que salvou a venda.',
'Comm_G_Credit_Nobody' => 'Se nenhuma dessas opções encontrar um representante ativo, a venda não gera comissão.',
'Comm_G_Credit_Note' => 'No PDV, deixar o representante em "Automático" usa as opções 2 e 3. O nome exibido ao lado de "Automático" é o do representante que será creditado.',
'Comm_G_T_When' => 'Quando as comissões são calculadas e atualizadas?',
'Comm_G_When_Intro' => 'As comissões são criadas pela primeira vez quando uma venda com status Concluída é salva, em qualquer um destes lugares:',
'Comm_G_When_Create' => 'Criar venda: quando a venda é salva como Concluída.',
'Comm_G_When_Edit' => 'Editar venda: salvar uma venda Concluída a recalcula do zero com o total, os pagamentos e o representante atuais, incluindo comissões que tinham sido canceladas.',
'Comm_G_When_Pos' => 'PDV: quando uma venda é concluída, incluindo um rascunho concluído posteriormente.',
'Comm_G_When_Payment' => 'Adicionar um pagamento a uma venda Concluída, o que permite que regras de Valor pago considerem pagamentos recebidos após a venda.',
'Comm_G_When_Cod' => 'Pagamento na entrega via transportadora: quando o dinheiro recolhido pela transportadora é registrado como pagamento na venda.',
'Comm_G_When_Not_Intro' => 'Estes NÃO criam comissões:',
'Comm_G_When_Not_Status' => 'Vendas salvas como Pendente ou Encomendado. Elas passam a gerar comissão quando são editadas e salvas como Concluída.',
'Comm_G_When_Not_Before' => 'Vendas salvas antes de o programa ou a regra existir. Elas não são calculadas em segundo plano. Abrir uma dessas vendas em Editar venda e salvá-la a calcula com as regras ativas na data da venda.',
'Comm_G_When_Not_Import' => 'Vendas importadas de um arquivo.',
'Comm_G_When_Not_Online' => 'Pedidos feitos na loja online.',
'Comm_G_T_Statuses' => 'Status das comissões',
'Comm_G_Meaning' => 'O que significa',
'Comm_G_S_Pending' => 'Acabou de ser calculada a partir de uma venda. Ninguém a verificou ainda. Aprove-a ou cancele-a no Relatório de Comissões.',
'Comm_G_S_Approved' => 'Verificada e aceita. É devida ao representante e pode ser incluída em um Recibo de Comissão. Se a venda mudar e o valor mudar, ela volta para Pendente para nova revisão.',
'Comm_G_S_Paid' => 'Incluída em um Recibo de Comissão. Definitiva: comissões pagas nunca são alteradas. Se a venda mudar depois, a diferença é adicionada como um Ajuste separado.',
'Comm_G_S_Cancelled' => 'Não será paga. Ela continua cancelada quando entram pagamentos ou devoluções depois. Salvar a venda em Editar venda, ou marcá-la no relatório e clicar em Recalcular, a calcula novamente.',
'Comm_G_Field' => 'Campo',
'Comm_G_T_Programs' => 'Programas de comissão',
'Comm_G_Programs_Body' => 'Um programa é um contêiner de regras, geralmente um por período ou campanha. Uma regra só funciona enquanto o programa dela estiver Ativo e a data da venda estiver dentro das datas do programa. Vários programas podem estar ativos ao mesmo tempo, e todos se aplicam.',
'Comm_G_F_Program_Name' => 'Qualquer nome que ajude você a reconhecer o programa, por exemplo "4º tri 2026" ou "Black Friday".',
'Comm_G_F_Program_Active' => 'Desmarque para pausar todas as regras do programa de uma vez. As comissões já criadas não são afetadas.',
'Comm_G_F_Program_From' => 'Vendas com data anterior a este dia são ignoradas pelo programa. Deixe vazio para não ter data de início.',
'Comm_G_F_Program_To' => 'Vendas com data posterior a este dia são ignoradas pelo programa. Deixe vazio para um programa que nunca termina.',
'Comm_G_T_Agents' => 'Representantes de vendas',
'Comm_G_Agents_Body' => 'Um representante de vendas é a pessoa que recebe comissão. Um representante não precisa ser usuário do sistema: indicadores ou revendedores externos também podem ser representantes e recebem sempre que são escolhidos em uma venda.',
'Comm_G_F_Agent_Name' => 'O nome exibido nas vendas, no relatório e nos recibos.',
'Comm_G_F_Agent_Code' => 'Referência opcional, como um número de funcionário. Pesquisável na lista de representantes.',
'Comm_G_F_Agent_User' => 'Vincula o representante a um usuário da equipe. As vendas que esse usuário faz (ou para as quais é escolhido como vendedor no PDV) passam a ser creditadas a este representante automaticamente.',
'Comm_G_F_Agent_Active' => 'Representantes inativos não recebem nada em novas vendas e somem dos seletores de representante. As comissões anteriores deles permanecem.',
'Comm_G_T_Rules' => 'Regras de comissão: cada campo explicado',
'Comm_G_Rules_Body' => 'Uma regra decide quanto é pago em uma venda. Use a caixa "Testar uma regra" acima para verificar uma regra antes de salvá-la.',
'Comm_G_F_Rule_Program' => 'O programa ao qual a regra pertence. A regra só funciona enquanto esse programa estiver ativo e dentro do prazo.',
'Comm_G_F_Rule_Type' => 'Percentual paga uma parte do valor base. Fixo paga o mesmo valor em cada venda qualificada, qualquer que seja o tamanho dela.',
'Comm_G_F_Rule_Source' => 'Sobre o que o percentual é calculado. Total da venda é o total geral da venda. Valor pago é o que o cliente tinha pago quando a comissão foi calculada.',
'Comm_G_F_Rule_Value' => 'O percentual (5 significa 5%) ou o valor fixo, dependendo do Tipo.',
'Comm_G_F_Rule_Min' => 'Opcional. Vendas cujo valor base esteja abaixo deste não geram nada por esta regra. Uma venda exatamente igual ao limite gera.',
'Comm_G_F_Rule_Cap' => 'Opcional. O máximo que esta regra pode pagar em uma venda. Funciona para regras percentuais e fixas.',
'Comm_G_F_Rule_Applies' => 'Todos os representantes: todos os representantes recebem por esta regra. Representante específico: apenas o representante selecionado. Uma regra de Representante específico sem representante selecionado nunca paga ninguém.',
'Comm_G_F_Rule_Priority' => 'Em um programa configurado como "Somente a regra de maior prioridade paga", a regra qualificada com o maior número vence e as demais são ignoradas. Em caso de empate, uma regra de Representante específico vence uma regra de Todos os representantes. Em um programa configurado como "Todas as regras correspondentes pagam", a Prioridade apenas define a ordem.',
'Comm_G_F_Rule_Active' => 'Desmarque para pausar apenas esta regra. As comissões que ela já criou não são afetadas.',
'Comm_G_T_Stacking' => 'Várias regras em uma venda',
'Comm_G_Stacking_Body' => 'Cada programa decide como suas regras se combinam (a configuração "Quando várias regras correspondem" no programa).

Somente a regra de maior prioridade paga (o padrão para novos programas): as regras são testadas da maior Prioridade para a menor, e a primeira que se qualifica para a venda paga. Uma regra se qualifica quando a venda atinge o limite mínimo dela e o resultado é maior que 0. Isso facilita criar faixas: "7% em vendas de 10.000 ou mais" com prioridade 10 e "5%" com prioridade 0. Para dar uma taxa especial à Sara, adicione uma regra de Representante específico para ela com prioridade maior que a da regra de Todos os representantes.

Todas as regras correspondentes pagam: todas as regras correspondentes pagam e os valores se somam. Uma regra de Todos os representantes de 3% mais uma regra de Representante específico de 2% para a Sara dá 5% à Sara.

Os programas são independentes entre si: cada programa ativo paga por conta própria, então uma venda pode gerar comissão de um programa base e de um programa de campanha ao mesmo tempo.',
'Comm_G_T_Paying' => 'Pagando representantes com Recibos de Comissão',
'Comm_G_Paying_Body' => 'Abra Recibos de Comissão e clique em Adicionar. Escolha o representante: as comissões Aprovadas dele são listadas. Marque as que você está pagando; o Valor é preenchido com o total delas, e você pode ajustá-lo. A Ref. é preenchida automaticamente (CR-000001, CR-000002...), e você pode adicionar a forma de pagamento, a data e uma observação.

Salvar o recibo marca as comissões selecionadas como Pagas e as vincula ao recibo. Somente comissões Aprovadas podem ser pagas, então aprove-as primeiro no Relatório de Comissões.

Ajustes negativos (valores pagos a mais ao representante) também são listados. Marque-os junto com as próximas comissões do representante para que sejam descontados desse pagamento.

Um recibo é apenas o registro do pagamento: ele não cria uma despesa nem movimenta dinheiro nas suas contas. Se você acompanha os pagamentos em Despesas ou na Contabilidade, registre-os lá também.',
'Comm_G_T_Snapshot' => 'Quando uma venda muda',
'Comm_G_Snapshot_Body' => 'As comissões acompanham a venda. Sempre que uma venda com comissões muda, elas são recalculadas a partir dos valores atuais: o total da venda menos as devoluções recebidas e o valor pago menos os reembolsos.

Comissões não pagas (Pendentes ou Aprovadas) são simplesmente atualizadas. Uma comissão Aprovada cujo valor muda volta para Pendente para que alguém a verifique novamente. Uma que não é mais devida (venda excluída, totalmente devolvida, representante alterado) é removida.

Comissões pagas nunca são alteradas. A diferença se torna uma nova linha Pendente marcada como Ajuste: positiva quando há mais a pagar (por exemplo, o restante de uma venda com Valor pago foi quitado), negativa quando o representante recebeu a mais (por exemplo, após uma devolução). Aprove-a e inclua-a no próximo recibo do representante.

Cada comissão mantém os termos da regra (tipo, taxa, limite, teto) do momento em que foi gerada. Alterar ou desativar uma regra depois não reprecifica vendas antigas quando elas são recalculadas.',
'Comm_G_T_Permissions' => 'Quem pode fazer o quê',
'Comm_G_Permission' => 'Permissão',
'Comm_G_Lets_You' => 'O que permite',
'Comm_G_P_View' => 'Ver todas as páginas de Comissões: programas, representantes, regras, recibos, o relatório e este guia.',
'Comm_G_P_Add' => 'Criar programas, representantes e regras, e registrar Recibos de Comissão (pagar representantes).',
'Comm_G_P_Edit' => 'Editar programas, representantes e regras, e aprovar ou cancelar comissões no Relatório de Comissões.',
'Comm_G_P_Delete' => 'Excluir programas, representantes e regras.',
'Comm_G_T_Faq' => 'Perguntas e respostas',
'Comm_G_Q_Empty' => 'Configurei tudo, mas o Relatório de Comissões está vazio.',
'Comm_G_A_Empty' => 'Verifique se: a venda foi salva depois que a regra foi criada; a venda está Concluída; a venda tem um representante (escolhido na venda, ou o usuário que a fez está vinculado a um representante); o programa está ativo e a data da venda está dentro das datas dele; a regra está ativa e se aplica a esse representante; e a venda atinge ou supera o valor mínimo da regra. Verifique também o filtro de data do relatório: ele filtra pela data em que a comissão foi calculada.',
'Comm_G_Q_Twice' => 'Um representante recebeu duas comissões em uma venda.',
'Comm_G_A_Twice' => 'Duas regras pagaram: ou o programa está definido como "Todas as regras correspondentes pagam", ou as regras estão em dois programas ativos diferentes (cada programa paga por conta própria). Defina o programa como "Só a regra de maior prioridade paga" se apenas uma deve pagar. Salvar uma venda novamente nunca duplica uma comissão.',
'Comm_G_Q_Rate' => 'Se eu mudar a taxa de uma regra, as comissões antigas mudam?',
'Comm_G_A_Rate' => 'Não. Cada comissão mantém as condições da regra sob a qual foi gerada, mesmo quando a venda é recalculada depois. A nova taxa é usada nas comissões geradas a partir de agora.',
'Comm_G_Q_Return' => 'O cliente devolveu as mercadorias. O que acontece com a comissão?',
'Comm_G_A_Return' => 'Ela é reduzida automaticamente. Uma devolução recebida diminui o total da venda e um reembolso diminui o valor pago. Se a comissão ainda não foi paga, ela é atualizada (ou removida em uma devolução total). Se já foi paga, um Ajuste negativo é adicionado e descontado do próximo recibo do representante.',
'Comm_G_Q_Wrong_Agent' => 'Creditei o representante errado. Como corrijo?',
'Comm_G_A_Wrong_Agent' => 'Edite a venda, escolha o Representante de Vendas correto e salve. As comissões passam para o representante correto. Se o primeiro representante já tiver sido pago, um Ajuste negativo é adicionado para ele.',
'Comm_G_Q_Inactive' => 'O que acontece quando desativo um representante?',
'Comm_G_A_Inactive' => 'Ele deixa de ganhar em novas vendas e fica oculto nos seletores de representante. As comissões existentes continuam, ainda podem ser aprovadas e pagas, e ainda acompanham as alterações nas vendas. Uma venda salva com esse representante escolhido não passa para outro representante.',
'Comm_G_Q_Partial' => 'Como as regras de Valor Pago lidam com pagamentos parciais?',
'Comm_G_A_Partial' => 'Uma venda não paga não gera nada. A comissão é criada quando o dinheiro é recebido pela primeira vez (no checkout ou quando um pagamento é adicionado) e cresce conforme entram mais pagamentos. Se parte dela já foi paga, o restante chega como um Ajuste positivo.',
'Comm_G_Q_Undo' => 'Posso desfazer um pagamento ou um cancelamento?',
'Comm_G_A_Undo' => 'Um pagamento, não: Pago é definitivo e os recibos não podem ser editados nem excluídos, então confira as comissões marcadas e o valor antes de salvar. Um cancelamento, sim: marque a linha no Relatório de Comissões e clique em Recalcular, ou salve a venda novamente em Editar venda.',
'Comm_G_Q_Dates' => 'Qual data as datas do programa usam?',
'Comm_G_A_Dates' => 'A própria data da venda, não o dia em que ela foi salva. Uma venda com data do mês passado só usa programas válidos no mês passado.',
'Comm_G_When_Changes' => 'Depois disso, qualquer alteração em uma venda que já tem comissões as atualiza automaticamente: pagamentos editados ou excluídos, devoluções e reembolsos, o status deixando de ser Concluída, ou a exclusão da venda.',
'Comm_G_F_Program_Mode' => 'O que acontece quando várias regras deste programa correspondem à mesma venda. "Só a regra de maior prioridade paga": as regras são testadas da Prioridade mais alta para baixo e a primeira que se qualifica paga. "Todas as regras correspondentes pagam": todas pagam e os valores se somam.',
'Comm_G_Q_Mode_Old' => 'Defini prioridades, mas as regras continuam se somando.',
'Comm_G_A_Mode_Old' => 'Esse programa está definido como "Todas as regras correspondentes pagam". Programas criados antes desta configuração existir mantêm esse comportamento para que seus pagamentos não mudem. Edite o programa e escolha "Só a regra de maior prioridade paga".',
'Comm_G_Q_Negative' => 'Por que existe uma comissão negativa?',
'Comm_G_A_Negative' => 'É um Ajuste: o representante recebeu mais do que a venda gera agora, por causa de uma devolução, um reembolso, um total menor, uma troca de representante ou uma venda excluída. Aprove-o e marque-o no próximo recibo do representante para que seja descontado.',
'Comm_Rule_Mode' => 'Quando várias regras correspondem',
'Comm_Mode_Highest' => 'Só a regra de maior prioridade paga',
'Comm_Mode_All' => 'Todas as regras correspondentes pagam (os valores se somam)',
'Comm_Mode_Highest_Short' => 'A maior prioridade vence',
'Comm_Mode_All_Short' => 'As regras se somam',
'Comm_Mode_Highest_Help' => 'As regras são testadas da Prioridade mais alta para baixo; a primeira que se qualifica para a venda paga e as outras são ignoradas. Bom para faixas, por exemplo 7% acima de 10,000 com prioridade 10 e 5% para todo o resto com prioridade 0.',
'Comm_Mode_All_Help' => 'Todas as regras que correspondem ao representante pagam sobre a venda, então os valores se somam. A prioridade só define a ordem.',
'Comm_Priority_Help_Highest' => 'Este programa paga apenas a regra de maior prioridade que se qualifica. Dê a esta regra uma Prioridade maior que a das regras que ela deve superar. Em caso de empate, uma regra de Representante Específico vence uma regra de Todos os Representantes.',
'Comm_Priority_Help_All' => 'Este programa paga todas as regras correspondentes, então esta regra se soma às outras. A prioridade só define a ordem.',
'Comm_Recalculate' => 'Recalcular',
'Comm_Recalculate_Help' => 'Recalcula as vendas das linhas marcadas a partir dos valores atuais, incluindo comissões que foram canceladas.',
'Comm_Adjustment' => 'Ajuste',
'Comm_Adjustment_Help' => 'Uma correção em uma comissão que já foi paga, porque a venda mudou depois. Um valor negativo é descontado do próximo recibo do representante.',
'Comm_Cancel_Confirm' => 'Cancelar as comissões selecionadas?',
'Comm_Cancel_Confirm_Help' => 'Elas não serão pagas e continuam canceladas quando pagamentos ou devoluções chegarem depois. Salvar a venda em Editar venda ou clicar em Recalcular as calcula novamente.',
'Fashion_Tiles_Hint' => 'Adicione seus próprios blocos (imagem, título e link) para substituir os blocos automáticos de categoria.',

