// Restaurant Management — guide page
'Rst_Guide' => 'Guia',
'Rst_Guide_Subtitle' => 'Configure o restaurante e aprenda como funciona um serviço, passo a passo',
'Rst_Guide_Module_Off' => 'O módulo Restaurante não está ativo para esta conta',
'Rst_Guide_Module_Off_Help' => 'Ele precisa do recurso Restaurante no seu plano e do módulo ativado em Configurações › Módulos. Pedidos online, cardápios por QR e reservas online ficam ocultos até lá.',
'Rst_Guide_Your_Setup' => 'Sua configuração',
'Rst_Guide_Your_Setup_Help' => 'Verificado com os seus próprios dados toda vez que você abre esta página. Siga de cima para baixo; as etapas opcionais podem ficar para depois.',
'Rst_Guide_Done_N' => '{done} de {total} concluídas',
'Rst_Guide_Optional' => 'Opcional',
'Rst_Guide_State_Done' => 'Concluído',
'Rst_Guide_State_Warn' => 'Requer atenção',
'Rst_Guide_State_Todo' => 'A fazer',
'Rst_Guide_Step_Db' => 'Atualização do banco de dados',
'Rst_Guide_Step_Db_Ok' => 'Todas as tabelas do restaurante estão no lugar.',
'Rst_Guide_Step_Db_Help' => 'Faltam algumas tabelas do restaurante. Execute a atualização mais recente do banco de dados (migrações do tenant) e recarregue esta página.',
'Rst_Guide_Step_Settings' => 'Configurações do restaurante',
'Rst_Guide_Step_Settings_Ok' => 'Tipos de pedido: {types}. Uma filial padrão está definida.',
'Rst_Guide_Step_Settings_Help' => 'Escolha os tipos de pedido que você aceita, a filial cujo estoque as vendas do restaurante usam, a taxa de serviço, as gorjetas e o arredondamento.',
'Rst_Guide_Step_Floor' => 'Áreas do salão e mesas',
'Rst_Guide_Step_Floor_Ok' => '{areas} áreas, {tables} mesas.',
'Rst_Guide_Step_Floor_Help' => 'Adicione suas áreas (Interna, Varanda…) e as mesas com o número de lugares. "Adicionar várias" cria T1–T20 de uma vez.',
'Rst_Guide_Step_Stations' => 'Estações de cozinha',
'Rst_Guide_Step_Stations_Ok' => '{n} estações.',
'Rst_Guide_Step_Stations_Help' => 'As estações (Grelha, Fritadeira, Frios, Sobremesas, Bebidas…) dividem a tela da cozinha para que cada cozinheiro veja apenas os seus pratos.',
'Rst_Guide_Step_Dishes' => 'Pratos e adicionais',
'Rst_Guide_Step_Dishes_Ok' => '{n} pratos configurados, {groups} grupos de adicionais.',
'Rst_Guide_Step_Dishes_Help' => 'Os pratos são os seus produtos normais. Em Restaurante › Cardápio, defina para eles uma estação, o tempo de preparo, as etiquetas alimentares e os grupos de adicionais (tamanhos, extras).',
'Rst_Guide_Step_Payments' => 'Pagamentos',
'Rst_Guide_Step_Payments_Ok' => '{n} formas de pagamento prontas, com dinheiro, e um cliente padrão para contas de clientes sem cadastro.',
'Rst_Guide_Step_Payments_Help' => 'As contas precisam de pelo menos uma forma de pagamento ativa, uma forma em dinheiro (o troco é dado em dinheiro) e um cliente padrão nas Configurações de sistema.',
'Rst_Guide_Step_Staff' => 'Permissões da equipe',
'Rst_Guide_Step_Staff_Help' => 'Funções que podem anotar pedidos: {waiters}; usar a tela da cozinha: {kitchen}; receber pagamentos: {cashiers}. Dê a cada função apenas o que aquele trabalho precisa (veja "Quem faz o quê").',
'Rst_Guide_Step_First' => 'Sua primeira conta',
'Rst_Guide_Step_First_Ok' => '{n} contas recebidas até agora.',
'Rst_Guide_Step_First_Help' => 'Acomode uma mesa de teste no mapa do salão, adicione um prato, envie-o, marque-o como pronto na tela da cozinha e receba o pagamento.',
'Rst_Guide_Step_Qr' => 'Pedido na mesa por QR',
'Rst_Guide_Step_Qr_On' => 'Ativado. {n} mesas têm QR code.',
'Rst_Guide_Step_Qr_Help' => 'Os clientes escaneiam um código na mesa, escolhem os pratos no celular e os enviam para o pedido da mesa. Ative em Configurações do Restaurante e depois imprima os códigos.',
'Rst_Guide_Step_Booking' => 'Reserva de mesa online',
'Rst_Guide_Step_Booking_On' => 'Ativado. As reservas da loja online chegam em Reservas para confirmação.',
'Rst_Guide_Step_Booking_Help' => 'Permita que os clientes reservem uma mesa pela loja online. Defina os horários de reserva, o intervalo e o maior grupo nas Configurações do Restaurante.',
'Rst_Guide_Step_Store' => 'Loja online e o tema Restaurante',
'Rst_Guide_Step_Store_On' => 'O tema Restaurante está ativo. Os pedidos online chegam à cozinha: {mode}.',
'Rst_Guide_Step_Store_Help' => 'Em Loja Online › Configurações, escolha o tema "Restaurante": a página inicial vira o seu cardápio, com adicionais, retirada / entrega e reserva de mesa.',
'Rst_Guide_How' => 'Como funciona',
'Rst_Guide_Service' => 'Um serviço, passo a passo',
'Rst_Guide_Service_1_T' => 'Acomodar',
'Rst_Guide_Service_1' => 'No mapa do salão, escolha uma mesa livre, informe o número de pessoas e o garçom e clique em "Acomodar clientes e anotar o pedido". Um grupo com reserva é acomodado a partir da reserva.',
'Rst_Guide_Service_2_T' => 'Pedir',
'Rst_Guide_Service_2' => 'Toque nos pratos na tela do pedido. Escolha adicionais, lugar e etapa; adicione uma observação para a cozinha. Segure uma etapa para liberá-la depois.',
'Rst_Guide_Service_3_T' => 'Enviar',
'Rst_Guide_Service_3' => '"Enviar" coloca os novos pratos em uma única comanda da cozinha. Pratos ainda não enviados podem ser alterados ou removidos; depois disso só podem ser anulados com um motivo.',
'Rst_Guide_Service_4_T' => 'Preparar',
'Rst_Guide_Service_4' => 'A tela da cozinha mostra a comanda em cada estação. Os cozinheiros a iniciam, marcam os pratos à medida que ficam prontos e a concluem quando tudo estiver pronto.',
'Rst_Guide_Service_5_T' => 'Servir',
'Rst_Guide_Service_5' => 'Os pratos prontos aparecem no mapa de mesas e na tela do pedido. O garçom os leva e toca em "Marcar como servido".',
'Rst_Guide_Service_6_T' => 'Conta',
'Rst_Guide_Service_6' => '"Conta e pagamento" imprime a conta e recebe o pagamento: conta inteira, dividida igualmente ou por item. Cada pagamento é uma venda normal no PDV.',
'Rst_Guide_Service_7_T' => 'Liberar',
'Rst_Guide_Service_7' => 'Quando tudo estiver pago, o pedido é fechado e a mesa passa para "Precisa de limpeza" (ou direto para livre, conforme as Configurações do restaurante).',
'Rst_Guide_Roles' => 'Quem faz o quê',
'Rst_Guide_Roles_Help' => 'As permissões do restaurante são concedidas por função em Permissões de grupo. Um usuário pode ter as permissões de várias funções.',
'Rst_Guide_Job' => 'Função',
'Rst_Guide_Give' => 'Conceda estas permissões',
'Rst_Guide_Job_Waiter' => 'Garçom',
'Rst_Guide_Job_Cook' => 'Cozinheiro',
'Rst_Guide_Job_Cashier' => 'Caixa',
'Rst_Guide_Job_Host' => 'Recepcionista / recepção',
'Rst_Guide_Job_Supervisor' => 'Supervisor',
'Rst_Guide_Job_Manager' => 'Gerente',
'Rst_Guide_Menu' => 'Cardápio, estações e adicionais',
'Rst_Guide_Menu_1' => 'Todo produto que você vende pode ser um prato. Restaurante › Cardápio (ou o cartão "Detalhes do prato" no formulário do produto) adiciona as informações do restaurante.',
'Rst_Guide_Menu_2' => 'Os grupos de adicionais reúnem opções com preço: "Tamanho" (escolha 1) ou "Extras" (até 3). As regras são verificadas em todos os pedidos, inclusive online.',
'Rst_Guide_Menu_3' => 'Um adicional pode consumir um ingrediente: vincule "Queijo extra" ao seu produto Queijo e cada um baixa esse estoque.',
'Rst_Guide_Menu_4' => 'Marque um prato como esgotado hoje com um único botão; ele volta sozinho amanhã. Os horários de refeição (café da manhã, almoço, jantar) limitam quando um prato é oferecido.',
'Rst_Guide_Menu_5' => 'Uma receita é um produto combo: com o estoque virtual de combos ativado, vender o prato baixa os componentes do estoque.',
'Rst_Guide_Kitchen' => 'Tela da cozinha',
'Rst_Guide_Kitchen_1' => 'Abra Restaurante › Cozinha em uma tela na cozinha. Escolha a estação; pratos sem estação aparecem em todas as estações.',
'Rst_Guide_Kitchen_2' => 'As comandas ficam âmbar e depois vermelhas enquanto esperam (Configurações do restaurante › atrasada após N minutos). Um bipe anuncia novas comandas.',
'Rst_Guide_Kitchen_3' => 'Iniciar → marcar os pratos → Concluir. "Pronto nesta estação" conclui apenas os pratos desta estação em uma comanda compartilhada.',
'Rst_Guide_Kitchen_4' => 'As comandas servidas ficam visíveis por 15 minutos para que um erro possa ser revertido. As comandas podem ser impressas em uma impressora de 80 mm.',
'Rst_Guide_Kitchen_5' => 'Pedidos da loja online e dos QR codes das mesas são marcados como "Online" ou "QR" na comanda.',
'Rst_Guide_Bills' => 'Contas e pagamentos',
'Rst_Guide_Bills_1' => 'Cada pagamento é uma venda normal no PDV: estoque, caixa, contabilidade, pontos de fidelidade e faturamento eletrônico funcionam como no PDV.',
'Rst_Guide_Bills_2' => 'A taxa de serviço é uma porcentagem dos pratos antes dos impostos, para consumo no local (ou para todos os pedidos, conforme sua configuração). As gorjetas são uma porcentagem predefinida ou um valor.',
'Rst_Guide_Bills_3' => 'Um desconto exige a permissão "Descontos do restaurante" e é limitado pelo maior desconto definido nas Configurações do restaurante.',
'Rst_Guide_Bills_4' => 'O arredondamento é feito para baixo, até o seu incremento, a favor do cliente, no pagamento que quita a conta.',
'Rst_Guide_Bills_5' => 'Dividir igualmente: uma venda, uma linha de pagamento por pessoa (partes até o centavo). Dividir por item: os pratos de cada cliente viram uma venda própria; escolha um lugar para selecionar os pratos dele.',
'Rst_Guide_Bills_6' => 'Se a conta mudou depois de ser exibida (um prato adicionado por QR code, uma gorjeta alterada), o pagamento é recusado para que o cliente nunca seja cobrado por algo que não viu.',
'Rst_Guide_Bills_7' => 'Pratos pagos não podem ser cancelados. Se o restante não pago de um pedido for cancelado, o pedido é fechado como pago e a mesa pode ser liberada.',
'Rst_Guide_Bookings' => 'Reservas e lista de espera',
'Rst_Guide_Bookings_1' => 'As reservas bloqueiam uma mesa pela sua duração (padrão nas Configurações do restaurante). Duas reservas nunca podem se sobrepor em uma mesa.',
'Rst_Guide_Bookings_2' => 'O mapa de mesas mostra a próxima reserva de cada mesa e avisa quando ela está próxima; "Chegaram — acomodar" acomoda o grupo.',
'Rst_Guide_Bookings_3' => 'Após o tempo de não comparecimento, um grupo atrasado pode ser marcado como não compareceu; um erro pode ser desfeito.',
'Rst_Guide_Bookings_4' => 'A lista de espera mantém em ordem os clientes sem reserva, com o tempo de espera informado. Ligue ou mande WhatsApp quando uma mesa estiver pronta e acomode-os.',
'Rst_Guide_Bookings_5' => 'As reservas online chegam como "Reservada" (um contador na barra lateral as indica) para você confirmar.',
'Rst_Guide_Online' => 'Pedidos online, cardápios QR e reservas online',
'Rst_Guide_Online_1' => 'Com o tema de loja Restaurante, a página inicial da loja online é o seu cardápio, com adicionais e filtros de dieta; os clientes pagam no checkout normalmente.',
'Rst_Guide_Online_2' => '"Pedidos online para a cozinha" define quando eles chegam à tela da cozinha: ao serem feitos (pagos, ou de um cliente conectado pagando na entrega / retirada), ao serem aceitos, ou nunca.',
'Rst_Guide_Online_3' => 'Os QR codes das mesas (Configuração do salão › QR codes das mesas) abrem o cardápio daquela mesa. "Novo link" desativa um código impresso.',
'Rst_Guide_Online_4' => 'Os pedidos por QR aguardam no pedido da mesa até um garçom enviá-los, a menos que "Enviar pedidos QR direto para a cozinha" esteja ativado. Os clientes pagam com a equipe.',
'Rst_Guide_Online_5' => 'A reserva online só oferece horários em que uma mesa adequada ao grupo esteja livre durante toda a reserva, e limita cada número de telefone a 3 reservas futuras.',
'Rst_Guide_Online_6' => 'Tudo isso faz parte da loja online: ela precisa estar ativada e incluída no seu plano.',
'Rst_Guide_Reports' => 'Painel e relatórios',
'Rst_Guide_Reports_1' => 'O painel compara hoje com o mesmo dia da semana passada: vendas, contas, clientes, conta média, cancelamentos e descontos, além do que está acontecendo agora.',
'Rst_Guide_Reports_2' => 'As vendas são as contas do restaurante mais os pedidos online que chegaram à cozinha. As vendas de pratos e as margens são antes dos impostos, usando o custo de cada produto.',
'Rst_Guide_Reports_3' => 'Relatórios: vendas por dia e forma de pagamento, pratos, estornos e cancelamentos (com motivos), equipe, tempos de cozinha e reservas — cada um exporta para Excel.',
'Rst_Guide_Reports_4' => 'Funcionários limitados a algumas filiais veem apenas as suas filiais; pedidos sem filial são compartilhados por todos.',
'Rst_Guide_Faq' => 'Bom saber',
'Rst_Guide_Faq_1_Q' => 'Um pedido para viagem foi pago antes de eu tocar em "Enviar". Ele será preparado?',
'Rst_Guide_Faq_1_A' => 'Sim. Pagar envia para a cozinha todos os pratos que ainda não tinham sido enviados.',
'Rst_Guide_Faq_2_Q' => 'Por que não consigo liberar uma mesa?',
'Rst_Guide_Faq_2_A' => 'O pedido dela ainda tem pratos não pagos. Receba o pagamento, cancele o que não foi consumido ou cancele o pedido (somente quando nada tiver sido pago).',
'Rst_Guide_Faq_3_Q' => 'Duas mesas foram juntadas. O que acontece com os pedidos delas?',
'Rst_Guide_Faq_3_A' => '"Juntar mesas" move os pratos (e quaisquer pagamentos) da segunda mesa para o pedido da mesa principal; "Separar" divide as mesas novamente.',
'Rst_Guide_Faq_4_Q' => 'Os pagamentos com cartão podem usar Stripe aqui?',
'Rst_Guide_Faq_4_A' => 'Não. Os pagamentos com cartão via Stripe exigem o formulário de cartão do PDV; para uma maquininha, adicione uma forma de pagamento como "Cartão" e use-a na conta.',
'Rst_Guide_Faq_5_Q' => 'Um prato está sem estoque em apenas uma filial.',
'Rst_Guide_Faq_5_A' => 'O estoque é baixado da filial do pedido (a área da mesa ou, se não houver, a filial padrão nas Configurações do restaurante). Use "Esgotado hoje" para interromper os pedidos rapidamente.',
'Rst_Guide_Faq_6_Q' => 'Preciso de uma impressora?',
'Rst_Guide_Faq_6_A' => 'Não. Contas, recibos e comandas da cozinha são impressos pelo navegador em qualquer impressora; impressoras de recibo de 80 mm são as mais indicadas.',
