'Bkm_Guide_Faq' => 'Perguntas',
'Bkm_Guide_Faq_1_Q' => 'Por que um serviço não aparece no site?',
'Bkm_Guide_Faq_1_A' => 'Ele precisa de dados de reserva (Serviços), "Mostrar no site" ativado, o produto ativo e — para escolher um horário — alguém reservável online que o realize.',
'Bkm_Guide_Faq_2_Q' => 'Por que não há horários livres?',
'Bkm_Guide_Faq_2_A' => 'Verifique o horário de trabalho da equipe, folgas, feriados e afastamentos aprovados, a antecedência mínima e com quantos dias de antecedência os clientes podem reservar.',
'Bkm_Guide_Faq_3_Q' => 'Dois clientes podem pegar o mesmo horário?',
'Bkm_Guide_Faq_3_A' => 'Não. O horário é verificado de novo quando o cliente reserva, e uma reserva temporária ou confirmada o bloqueia. Aulas compartilham vagas até o limite.',
'Bkm_Guide_Faq_4_Q' => 'O que acontece quando uma reserva temporária expira?',
'Bkm_Guide_Faq_4_A' => 'O horário fica livre de novo para outras pessoas. A reserva continua em Solicitações até você respondê-la (ou é cancelada se o sinal não foi pago).',
'Bkm_Guide_Faq_5_Q' => 'Os clientes precisam de uma conta?',
'Bkm_Guide_Faq_5_A' => 'Não. Eles recebem um link privado para a página da reserva. Contas da loja e do portal também listam as reservas.',
'Bkm_Guide_Faq_6_Q' => 'Para onde vai o dinheiro?',
'Bkm_Guide_Faq_6_A' => 'Os sinais vão para o seu provedor de pagamento; o restante é cobrado no PDV quando você cobra a reserva. Os relatórios contabilizam a receita dessas vendas.',
'Bkm_Guide_Faq_7_Q' => 'Por que um cliente não recebeu um e-mail?',
'Bkm_Guide_Faq_7_A' => 'Abra a reserva: a lista de mensagens informa se cada e-mail foi enviado, falhou ou foi ignorado, e por quê.',
