'Mkg_Guide_Faq' => 'Perguntas frequentes',
'Mkg_Guide_Faq_1_Q' => 'Minha campanha fica em Enviando e nada é enviado.',
'Mkg_Guide_Faq_1_A' => 'O processo de envio em segundo plano não a pegou. Após 30 minutos sem progresso, o botão Enviar Agora volta a aparecer: clique nele para retomar. Se isso continuar acontecendo, peça ao administrador da plataforma para verificar se as tarefas em segundo plano (o queue worker) estão em execução.',
'Mkg_Guide_Faq_2_Q' => 'Os destinatários mostram "Ignorado: canal de e-mail desativado".',
'Mkg_Guide_Faq_2_A' => 'Ative Habilitar e-mail nas Configurações de Marketing e depois envie a campanha novamente.',
'Mkg_Guide_Faq_3_Q' => 'Os destinatários mostram "Nenhum servidor de e-mail configurado".',
'Mkg_Guide_Faq_3_A' => 'As campanhas de e-mail só são enviadas pelo seu próprio servidor de e-mail. Adicione-o em Configurações > Configurações de e-mail.',
'Mkg_Guide_Faq_4_Q' => 'Menos pessoas receberam a mensagem do que as que estão no meu segmento.',
'Mkg_Guide_Faq_4_A' => 'Clientes sem endereço de e-mail (E-mail) ou número de telefone (SMS, WhatsApp) são ignorados. Abra a campanha para ver quem foi ignorado e por quê.',
'Mkg_Guide_Faq_5_Q' => 'Enviado significa que o cliente recebeu?',
'Mkg_Guide_Faq_5_A' => 'Enviado significa que o seu servidor de e-mail ou gateway aceitou a mensagem. A entrega na caixa de entrada, as aberturas e a filtragem de spam não são rastreadas.',
'Mkg_Guide_Faq_6_Q' => 'Posso editar uma campanha depois de enviá-la?',
'Mkg_Guide_Faq_6_A' => 'Não. Campanhas em envio ou enviadas ficam bloqueadas; crie uma nova campanha.',
'Mkg_Guide_Faq_7_Q' => 'Minhas mensagens de WhatsApp não estão chegando.',
'Mkg_Guide_Faq_7_A' => 'Depois de 24 horas da última mensagem do cliente, o WhatsApp só entrega modelos aprovados pela Meta. Use a WhatsApp Cloud API e escolha um modelo aprovado na campanha.',
'Mkg_Guide_Faq_8_Q' => 'Se eu enviar uma campanha novamente, os clientes vão recebê-la duas vezes?',
'Mkg_Guide_Faq_8_A' => 'Retomar uma campanha travada só envia para os destinatários ainda pendentes, então ninguém que já foi alcançado recebe a mensagem novamente. Enviar novamente uma campanha com falha recomeça com uma lista nova.',

