'Pd_Guide_How_Title' => 'Como funciona',
'Pd_Guide_How_Intro' => 'Um dispositivo de PDV é um terminal de cartão ou uma impressora fiscal ao lado do caixa. O Stocky envia o valor, aguarda o cliente pagar e registra o pagamento somente depois que o dispositivo o aprova.',
'Pd_Guide_Step_1' => 'Adicione o dispositivo aqui: modelo, armazém e a forma de pagamento com que os pagamentos com cartão são registrados (por exemplo, "Cartão de crédito").',
'Pd_Guide_Step_2' => 'Escolha como o Stocky acessa o dispositivo: um bridge local no computador do caixa ou a API em nuvem do seu provedor. Informe os IDs e as chaves fornecidos pelo seu banco ou provedor.',
'Pd_Guide_Step_3' => 'Clique em Testar conexão. Dispositivos com bridge devem ser testados a partir do computador do caixa onde o bridge está em execução.',
'Pd_Guide_Step_4' => 'No PDV, escolha essa forma de pagamento, clique em "Cobrar no dispositivo" e deixe o cliente pagar. A venda pode ser concluída assim que o dispositivo aprovar.',
'Pd_Guide_Step_5' => 'Confira em Transações os pagamentos com cartão feitos sem venda (por exemplo, um checkout abandonado) e anule-os ou reembolse-os.',
'Pd_Guide_Bridge_Text' => 'Para dispositivos controlados pelo SDK de um fabricante no PC do caixa (pareamento USB, serial ou LAN). O navegador não pode usar o SDK diretamente, então um pequeno programa bridge o encapsula e fica escutando neste computador.',
'Pd_Guide_Bridge_Point_1' => 'O PDV envia cada solicitação para a URL do bridge a partir do navegador do caixa; o servidor do Stocky nunca precisa acessar a rede da sua loja.',
'Pd_Guide_Bridge_Point_2' => 'As solicitações e respostas são assinadas com o segredo compartilhado, então uma aprovação não pode ser falsificada pelo navegador.',
'Pd_Guide_Bridge_Point_3' => 'Instale e inicie a ponte em cada computador que recebe pagamentos com cartão neste dispositivo.',
'Pd_Guide_Cloud_Text' => 'Para provedores que acessam o dispositivo pela internet. O servidor do Stocky chama a API, então nada precisa ser instalado no computador do caixa.',
'Pd_Guide_Cloud_Point_1' => 'A URL da API deve usar https:// em um endereço público.',
'Pd_Guide_Cloud_Point_2' => 'Enquanto o cliente paga, o Stocky consulta o status a cada 2 segundos, então o endpoint de status deve reconhecer o pagamento pela referência; se a API responder antes de o cartão terminar ("pending"), a consulta decide.',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'O IDE280 é uma caixa registradora fiscal de nova geração (YN ÖKC) com leitor de cartão. Normalmente é integrado pelo SDK ECR / GMP3 da Ingenico ou pelo serviço de integração do seu banco.',
'Pd_Guide_Ide280_Point_1' => 'Pareie o dispositivo com o computador do caixa conforme a documentação da Ingenico / do banco e depois aponte a ponte (ou as configurações da API) para ele.',
'Pd_Guide_Ide280_Point_2' => 'Os valores são enviados tanto em decimais quanto em kuruş (amount_minor), com a moeda TRY / 949.',
'Pd_Guide_Ide280_Point_3' => 'Com "Cupom fiscal completo", cada item leva o departamento do dispositivo correspondente à sua alíquota de IVA — faça os departamentos de IVA corresponderem à programação do dispositivo.',
'Pd_Guide_Protocol_Title' => 'Contrato da ponte / API',
'Pd_Guide_Protocol_Intro' => 'O Stocky se comunica em JSON com a ponte ou a API. Os caminhos abaixo são os padrões e podem ser alterados por dispositivo em Avançado.',
'Pd_Guide_Operation' => 'Operação',
