'Pd_Guide_When_Sale' => 'O caixa pressiona "Cobrar no dispositivo". Pode responder quando o cartão terminar ou imediatamente com o status "pending".',
'Pd_Guide_When_Status' => 'A cada 2 segundos enquanto o pagamento está pendente.',
'Pd_Guide_When_Cancel' => 'O caixa cancela enquanto aguarda o cartão.',
'Pd_Guide_When_Void' => 'Anulação de um pagamento (mesmo dia, valor total).',
'Pd_Guide_When_Refund' => 'Reembolso de parte ou da totalidade de um pagamento.',
'Pd_Guide_Request_Title' => 'Requisição',
'Pd_Guide_Request_Text' => 'O corpo que o Stocky envia em uma venda. Reembolso e anulação levam o pagamento original como "original".',
'Pd_Guide_Response_Title' => 'Resposta',
'Pd_Guide_Response_Text' => 'Os nomes dos campos são lidos de forma flexível (também dentro de "data"); "status" ou response_code "00" decide o resultado. Os números de cartão são armazenados mascarados.',
'Pd_Guide_Signing_Title' => 'Assinatura (ponte)',
'Pd_Guide_Signing_Text' => 'A ponte deve verificar a assinatura do Stocky e precisa assinar exatamente o corpo da sua resposta e repetir "reference" e "operation" — respostas não assinadas, ou sobre outra operação, são recusadas.',
'Pd_Guide_Browser_Title' => 'Acesso pelo navegador (ponte)',
'Pd_Guide_Browser_Text' => 'A página do PDV chama a ponte pelo navegador, então a ponte precisa responder com estes cabeçalhos CORS (inclusive no preflight OPTIONS).',
'Pd_Guide_Safety_Title' => 'Bom saber',
'Pd_Guide_Safety_1' => 'Uma venda só é salva com um pagamento no dispositivo aprovado para o mesmo valor; um pagamento no dispositivo nunca pode pagar duas vendas.',
'Pd_Guide_Safety_2' => 'Fechar a janela de pagamento depois que um cartão foi cobrado anula essa cobrança primeiro.',
'Pd_Guide_Safety_3' => 'Se o dispositivo não responder a tempo, o pagamento aparece como "Sem resposta": verifique o dispositivo e anule a cobrança em Transações se o cartão foi cobrado.',
'Pd_Guide_Safety_4' => 'Reembolsos e anulações aqui movimentam dinheiro apenas no cartão; não alteram a venda. Registre as mercadorias devolvidas em Devoluções de Vendas.',
