'Cd_Err_invalid' => 'Informe um nome de domínio válido, como shop.example.com.',
'Cd_Err_is_central' => 'Este é um domínio reservado da plataforma.',
'Cd_Err_duplicate' => 'Este domínio já está em uso.',
'Cd_Err_limit_reached' => 'Você atingiu o número de domínios personalizados permitido pelo seu plano.',
'Cd_Err_not_verified' => 'Verifique o domínio antes de defini-lo como principal.',
'Cd_Err_no_records' => 'Nenhum registro DNS encontrado ainda. A propagação pode levar alguns minutos.',
'Cd_Err_mismatch' => 'Registros DNS encontrados, mas eles não apontam para este servidor.',
'Cd_Err_lookup_failed' => 'A consulta DNS falhou. Tente novamente em instantes.',
'Cd_Err_unknown' => 'A verificação falhou. Confira as configurações de DNS.',
'Cd_Found_Records' => 'Registros encontrados',
'Cd_Guide_Title' => 'Como funciona',
'Cd_Guide_1' => 'Adicione o domínio que você possui, por exemplo shop.example.com.',
'Cd_Guide_2' => 'Entre no seu provedor de domínio (GoDaddy, Namecheap, Cloudflare...) e crie o registro DNS exibido.',
'Cd_Guide_3' => 'Volte e clique em Verificar DNS. Depois de verificado, seu espaço de trabalho, a loja online e o portal do cliente respondem nesse domínio.',
'Cd_Guide_4' => 'O subdomínio da plataforma continua funcionando junto com o domínio personalizado.',
'Cd_Cloudflare_Note' => 'Usuários do Cloudflare: defina o registro como DNS only (nuvem cinza) até a verificação terminar.',
'Perm_custom_domains' => 'Domínio personalizado (Configurações > Domínio personalizado)',
'List_Too_Big_All' => 'Esta lista tem mais de {count} linhas, então a opção Todos está desativada. Exibindo 100 linhas por página. Use a busca ou os filtros para refinar.',
'List_Too_Big_Export' => 'Esta lista tem mais de {count} linhas, o que é demais para exportar de uma vez. Use a busca ou os filtros para refinar.',
'PartiallyPaid' => 'Parcialmente pago',
'Ord_Guide_PayAuto_Tip' => 'Atualiza sozinho quando pagamentos são registrados na venda. Clique para ver como registrar um pagamento.',
'Ord_Guide_PayAuto_Intro' => 'Esta coluna mostra quanto do pedido já foi pago. Ela começa pela escolha do cliente no checkout e depois se atualiza sozinha à medida que pagamentos são registrados na venda criada ao confirmar o pedido. Ela não pode ser editada nesta página.',
'Ord_Guide_PayAuto_Paid' => 'O valor total foi recebido. Se o cliente pagou online por um gateway de pagamento, confirmar o pedido cria a venda como Paga e registra o pagamento para você. Caso contrário, o status muda para Pago quando os pagamentos da venda cobrirem o total.',
'Ord_Guide_PayAuto_Partial' => 'Um pagamento foi registrado na venda, mas parte do total ainda está pendente.',
'Ord_Guide_PayAuto_Pending' => 'Nenhum pagamento foi recebido ainda: pagamento na entrega, transferência bancária ou outra forma de pagar depois. Confirmar o pedido cria a venda como Não paga, então você mesmo registra o dinheiro quando o receber. Veja os passos abaixo.',
'Ord_Guide_PayAuto_Note' => 'O Status do pagamento exibido aqui acompanha a venda: muda para Parcialmente pago ou Pago sozinho quando você salva um pagamento, e volta se você excluir um. A venda é o registro contábil, e é ela que alimenta seus relatórios de pagamentos e de lucro. Use Mostrar pagamentos na venda para revisar ou editar o que você lançou.',
'Ord_LinkedSale' => 'Venda vinculada',
'Ord_LinkedSale_Missing' => 'Nenhuma venda está vinculada a este pedido. A venda pode ter sido excluída, ou o pedido foi confirmado antes de os pedidos serem vinculados às vendas.',
'Sale_FromOnlineOrder' => 'Esta venda foi criada a partir do pedido online',
'Mod_Opencart_Desc' => 'Sincronização com a loja OpenCart: produtos, estoque e pedidos.',
'Int_Desc_Opencart' => 'Sincronize produtos, variantes, estoque e pedidos com sua loja OpenCart.',
'Perm_opencart_settings' => 'Integração com OpenCart',
'Oc_Hero_Desc' => 'Sincronize produtos, variantes, estoque e pedidos com sua loja OpenCart por meio do {company} Connector.',
'Oc_Connector' => '{company} Connector',
'Oc_Download_Connector' => 'Baixar para OpenCart 4',
'Oc_Connector_Help' => 'O OpenCart não tem API para produtos ou estoque, então esta pequena extensão é instalada primeiro na sua loja.',
'Oc_Secret' => 'Segredo do conector',
'Oc_Secret_Placeholder' => 'Do módulo {company} Connector',
'Oc_Secret_Help' => 'Abra o módulo {company} Connector no OpenCart e copie o segredo dele aqui. Ele é armazenado criptografado e nunca mais é exibido.',
'Oc_Store' => 'Loja OpenCart',
'Oc_Versions' => 'Conector {connector} no OpenCart {opencart}',
'Oc_Automation' => 'Automação',
'Oc_Auto_Orders' => 'Importar pedidos automaticamente',
'Oc_Auto_Orders_Help' => 'Novos pedidos e mudanças de status chegam assim que acontecem, com uma verificação a cada poucos minutos para pegar o que tiver escapado.',
'Oc_Auto_Stock' => 'Enviar estoque automaticamente',
'Oc_Auto_Stock_Help' => 'Cada movimentação de estoque atualiza a loja, e todo o estoque é conferido uma vez por hora.',
'Oc_Auto_Products' => 'Enviar alterações de produtos automaticamente',
'Oc_Auto_Products_Help' => 'Um produto criado ou editado aqui atualiza a loja: nome, preço, status e estoque.',
'Oc_Order_Statuses' => 'Status dos pedidos',
'Oc_Order_Statuses_Help' => 'O que cada status do OpenCart significa aqui. Eles foram definidos a partir da sua loja e só precisam ser alterados se você usa status personalizados.',
'Oc_Commit_Statuses' => 'Venda concluída',
'Oc_Commit_Statuses_Help' => 'A venda é concluída e o estoque é baixado. Mantenha igual aos status que subtraem estoque no OpenCart.',
'Oc_Paid_Statuses' => 'Pago',
'Oc_Paid_Statuses_Help' => 'É registrado um pagamento do que ainda está pendente.',
'Oc_Cancel_Statuses' => 'Cancelado',
'Oc_Cancel_Statuses_Help' => 'A venda é revertida: o estoque volta e os pagamentos dela são removidos.',
'Oc_Variants_Linked' => 'Variantes vinculadas',
'Oc_Push_Desc' => 'Cria no OpenCart os produtos e variantes que faltam e atualiza nome, preço, status e estoque dos vinculados. Descrições, imagens e categorias só são definidas quando o produto é novo ou não tem nenhuma, então o texto escrito no OpenCart é mantido.',
'Oc_Pull_Desc' => 'Importa os produtos do OpenCart, associando os existentes pelo modelo ou SKU e criando os demais. Os produtos vinculados recebem o nome e o preço do OpenCart.',
'Oc_Pull_Stock' => 'Usar as quantidades do OpenCart como estoque inicial dos novos produtos',
'Oc_Reset_Confirm' => 'Redefinir os vínculos de produtos? O histórico de pedidos mantém seus vínculos.',
'Oc_Stock_Desc' => 'Define a quantidade na loja de cada produto e variante vinculados igual ao estoque mantido aqui.',
'Oc_Orders_Desc' => 'Importa os pedidos da loja como vendas (referências como {ref}). Pedidos já importados só têm status e pagamento atualizados, então importar de novo é seguro.',
'Oc_Orders_Since' => 'Pedidos desde',
'Oc_Guide_1' => 'Na aba Conexão, baixe o {company} Connector.',
'Oc_Guide_2' => 'No painel do OpenCart, envie o arquivo em {installer} e clique em Install; depois instale o módulo em {modules}.',
'Oc_Guide_3' => 'Abra o módulo {name} e copie a URL da loja e o segredo.',
'Oc_Guide_4' => 'Cole-os na aba Conexão, salve e execute {test}. Isso também informa à loja para onde enviar os novos pedidos.',
'Oc_Guide_5' => 'Configure os produtos: importe se a loja já tem um catálogo, envie se o {company} tiver. Faça isso antes de depender do estoque automático, porque o {company} passa a ser a fonte dos números de estoque.',
'Oc_Guide_6' => 'Importe os pedidos recentes uma vez se quiser o histórico. A partir daí, os pedidos chegam sozinhos.',
'Oc_Identity_Title' => 'Os produtos são associados pelo modelo e SKU',
'Oc_Identity_Desc' => 'O código do produto aqui é associado ao modelo e ao SKU do OpenCart. Mantenha-os iguais nos dois lados. O estoque daqui é o número principal: a loja é atualizada a partir dele após cada pedido.',
'Oc_Options_Title' => 'Opções sem variantes',
'Oc_Options_Desc' => 'As variantes do OpenCart têm estoque próprio e correspondem às variantes daqui. Um produto que só tem opções, sem variantes criadas, é importado como um único produto e seu estoque não é dividido por opção.',
'Oc_Cancel_Title' => 'Pedidos cancelados',
'Oc_Cancel_Desc' => 'Cancelar um pedido no OpenCart reverte a venda dele aqui. Se a venda já foi entregue ou tem uma devolução, nada é desfeito: a venda é sinalizada nas observações e nos logs para você revisar.',
'Oc_Download_Connector_3' => 'Baixar para OpenCart 3',
'Oc_Opencart3_Title' => 'Lojas OpenCart 3',
'Oc_Opencart3_Desc' => 'O OpenCart 3 não tem variantes próprias, apenas opções. Um produto com uma opção (Tamanho, por exemplo) é sincronizado com estoque por valor de opção, que corresponde às variantes daqui. Um produto com várias opções tem as opções criadas sem estoque por combinação: o estoque fica no produto como um todo e as linhas de venda entram no produto.',
'Oc_G_Title' => 'Guia do OpenCart',
'Oc_G_Open_Settings' => 'Abrir configurações do OpenCart',
'Oc_G_Your_Setup' => 'Sua configuração',
'Oc_G_Your_Setup_Help' => 'Em que ponto este espaço de trabalho está. Os passos se atualizam conforme você avança.',
'Oc_G_Step_Install' => 'Instale o {company} Connector na sua loja',
'Oc_G_Step_Install_Help' => 'Uma pequena extensão que dá ao {company} acesso a produtos, estoque e pedidos. O OpenCart não tem API própria para isso.',
'Oc_G_Step_Connect' => 'Conecte a loja',
'Oc_G_Step_Connect_Help' => 'Cole a URL da loja e o segredo da página do módulo na aba Conexão, salve e execute Testar conexão.',
'Oc_G_Step_Connect_Done' => 'Conectado: conector {connector} no OpenCart {opencart}.',
'Oc_G_Step_Enable' => 'Ative a sincronização',
'Oc_G_Step_Enable_Help' => 'Nada se movimenta enquanto a integração estiver desativada; os webhooks da loja são confirmados e ignorados.',
'Oc_G_Step_Products' => 'Vincule os produtos',
'Oc_G_Step_Products_Help' => 'Importe o catálogo da loja ou envie o seu, para que todos os produtos dos dois lados estejam vinculados antes de o estoque começar a fluir.',
'Oc_G_Step_Products_Done' => '{n} produtos e {v} variantes vinculados.',
'Oc_G_Step_Orders' => 'Receba pedidos',
'Oc_G_Step_Orders_Help' => 'Depois de conectado, os novos pedidos chegam sozinhos. Faça um pedido de teste na loja para vê-lo aparecer em Vendas.',
'Oc_G_Step_Orders_No_Webhook' => 'Pedidos foram importados, mas nenhum chegou ainda pelo aviso da loja. Se a loja não conseguir acessar este endereço, os pedidos continuam chegando pela verificação a cada poucos minutos.',
'Oc_G_Step_Orders_Done' => 'A loja está enviando avisos de pedidos.',
'Oc_G_Install_Title' => 'Instale o conector',
'Oc_G_Install_Intro' => 'Escolha sua versão do OpenCart. O conector é instalado pelo próprio instalador de extensões do OpenCart; nenhum arquivo é editado à mão.',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'Baixe o conector para OpenCart 4.',
'Oc_G_I4_2' => 'No painel do OpenCart, abra {path}, envie o arquivo e clique em Install ao lado dele.',
'Oc_G_I4_3' => 'Abra {path}, encontre {name} e clique em Install e depois em Edit.',
'Oc_G_I3_1' => 'Baixe o conector para OpenCart 3.',
'Oc_G_I3_2' => 'No painel do OpenCart, abra {path}, envie o arquivo e aguarde os passos terminarem.',
'Oc_G_I3_3' => 'Abra {path}, encontre {name} e clique em Install e depois em Edit.',
'Oc_G_I_4' => 'A página do módulo mostra a URL da loja e um segredo. Copie os dois.',
'Oc_G_I_5' => 'De volta aqui, cole-os na aba Conexão, salve e execute {test}. Isso também informa à loja para onde enviar os avisos de pedidos.',
'Oc_G_Requirements' => 'O que a loja precisa',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 ou 4.0 em diante, PHP com cURL (padrão em qualquer hospedagem) e um endereço da loja acessível pela internet. Se a loja estiver em uma rede privada, os pedidos continuam chegando pela verificação que roda a cada poucos minutos, desde que este espaço de trabalho consiga acessar a loja.',
'Oc_G_First_Title' => 'A primeira sincronização',
'Oc_G_First_Shop_Has' => 'A loja já tem o catálogo',
'Oc_G_First_Shop_Has_Text' => 'Importe os produtos na aba Produtos. Os produtos são associados pelo modelo ou SKU aos seus códigos de produto e criados quando não existem; marque a opção de estoque para usar as quantidades da loja como estoque inicial.',
'Oc_G_First_Company_Has' => 'O {company} tem o catálogo',
'Oc_G_First_Company_Has_Text' => 'Envie os produtos. Os produtos que faltam são criados na loja com seu estoque; os existentes são vinculados pelo modelo ou SKU e atualizados.',
'Oc_G_First_Both' => 'Os dois lados têm produtos',
'Oc_G_First_Both_Text' => 'Importe primeiro, para que os produtos existentes da loja sejam vinculados em vez de duplicados, e depois envie para criar o que falta na loja. Mantenha os códigos de produto e os modelos iguais nos dois lados.',
'Oc_G_Stock_Master' => 'O {company} mantém o número do estoque',
'Oc_G_Stock_Master_Desc' => 'Após a primeira sincronização, a quantidade na loja é sempre gravada a partir do {company}. Editar uma quantidade no OpenCart não tem efeito duradouro: a próxima movimentação ou a verificação horária a sobrescreve.',
'Oc_G_How_Title' => 'Como funciona',
'Oc_G_T_Products' => 'Produtos',
'Oc_G_Products_1' => 'Um produto é associado pelo código daqui com o modelo e o SKU da loja. O vínculo é guardado, então renomear um produto depois não o quebra.',
'Oc_G_Products_2' => 'Quando o {company} envia um produto, ele define modelo, SKU, nome, preço, status e estoque. A descrição, a imagem e a categoria só são gravadas quando o produto é novo na loja ou não tem nenhuma, então o texto escrito no OpenCart é mantido.',
'Oc_G_Products_3' => 'Um produto oculto da loja online ou que não está à venda aqui não é criado na loja; um que já está vinculado é desativado lá.',
'Oc_G_T_Variants' => 'Variantes e opções',
'Oc_G_Variants_4' => 'O OpenCart 4 tem variantes reais (um produto com opções de Cor e Tamanho), cada uma com estoque próprio. Elas correspondem às suas variantes nos dois sentidos, e cada uma é associada pelo próprio modelo.',
'Oc_G_Variants_3' => 'O OpenCart 3 não tem variantes, apenas opções, com estoque por valor de opção. Um produto com uma opção (Tamanho, por exemplo) é sincronizado com estoque por valor, que corresponde às suas variantes. Um produto com várias opções tem as opções criadas sem estoque por combinação: o estoque fica no produto como um todo e as linhas de venda entram no produto.',
'Oc_G_Variants_Multi' => 'Um produto da loja que só tem opções, sem variantes criadas, é importado como um único produto; isso é anotado nos logs.',
'Oc_G_T_Stock' => 'Estoque',
'Oc_G_Stock_1' => 'Com a opção de estoque ativada, cada movimentação aqui (uma venda, uma devolução, uma compra, um ajuste, uma transferência) atualiza a loja em segundos, depois que a página responde, para que o caixa nunca espere pela loja.',
'Oc_G_Stock_2' => 'Uma vez por hora, cada produto vinculado é conferido e corrigido, o que cobre alterações em massa que o envio em tempo real não detecta. A aba Estoque envia tudo sob demanda.',
'Oc_G_Stock_3' => 'Serviços, produtos marcados como sempre em estoque e combos cujos componentes são ilimitados aparecem como sempre disponíveis na loja. Escolha um armazém na aba Conexão para contar só esse armazém; caso contrário, todos os armazéns são somados.',
'Oc_G_T_Orders' => 'Pedidos e status',
'Oc_G_Orders_1' => 'Um pedido novo ou alterado é anunciado pela loja na hora e lido de volta pela conexão assinada, então nada no próprio aviso é considerado confiável. A cada poucos minutos, uma verificação busca o que algum aviso deixou escapar. Cada pedido vira uma venda com a referência OC-<order number>; o cliente é associado pelo e-mail ou criado.',
'Oc_G_Col_List' => 'Lista de status',
'Oc_G_Col_Meaning' => 'O que faz aqui',
'Oc_G_Col_Default' => 'Definido a partir da sua loja',
'Oc_G_Default_Commit' => 'Os status que subtraem estoque no OpenCart (Pending, Processing, Shipped, Complete por padrão)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'As listas são preenchidas a partir da sua loja na primeira conexão e podem ser alteradas na aba Conexão. Mantenha a primeira lista igual aos status que subtraem estoque no OpenCart, para que os dois lados movimentem o estoque na mesma etapa.',
'Oc_G_Orders_3' => 'Um pedido com um item que não corresponde a nenhum produto fica retido, e o produto é importado da loja se existir lá. Os pedidos retidos são tentados novamente a cada verificação agendada; após doze tentativas, são registrados no log e deixados para você importar manualmente.',
'Oc_G_T_Cancel' => 'Cancelamentos e reembolsos',
'Oc_G_Cancel_1' => 'Quando um pedido atinge um status cancelado na loja, a venda dele aqui é revertida: o estoque volta, os pagamentos são removidos e a venda é excluída, exatamente como excluí-la na página Vendas faria.',
'Oc_G_Cancel_2' => 'Uma venda já entregue, com devolução ou aceita por uma autoridade fiscal nunca é revertida pela loja. Ela é sinalizada nas observações e nos logs para você revisar.',
'Oc_G_Cancel_3' => 'Se o pedido for restabelecido na loja depois, ele entra de novo como uma nova venda.',
'Oc_G_T_Automation' => 'Chaves de automação',
'Oc_G_Auto_1' => 'Importar pedidos automaticamente: avisos de pedidos e a verificação agendada. Desativado, os pedidos só chegam quando você os importa na aba Pedidos.',
'Oc_G_Auto_2' => 'Enviar estoque automaticamente: atualizações de estoque em tempo real e a verificação horária. Desativado, a loja só muda quando você envia o estoque manualmente.',
'Oc_G_Auto_3' => 'Enviar alterações de produtos automaticamente: um produto criado ou editado aqui atualiza a loja na hora. Desativado, use a aba Produtos.',
'Oc_G_T_Faq' => 'Perguntas',
'Oc_G_Q_Secret' => 'Testar conexão diz que o segredo não confere',
'Oc_G_A_Secret' => 'Abra o módulo {company} Connector no OpenCart e copie o segredo novamente; um módulo reinstalado recebe um novo. Cole-o na aba Conexão e salve antes de testar.',
'Oc_G_Q_Clock' => 'Testar conexão diz que o relógio da loja está muito diferente',
'Oc_G_A_Clock' => 'As requisições assinadas levam o horário e são recusadas quando os dois relógios diferem em mais de cinco minutos. Ajuste a data e a hora no servidor da loja.',
'Oc_G_Q_Redirect' => 'Testar conexão diz que a loja redireciona para outro endereço',
'Oc_G_A_Redirect' => 'Sua loja responde em um endereço diferente, normalmente https em vez de http ou com www. Use o endereço mostrado na mensagem como URL da loja.',
'Oc_G_Q_Not_Answering' => 'Testar conexão diz que o conector não respondeu',
'Oc_G_A_Not_Answering' => 'O endereço não é uma loja OpenCart, ou o módulo não está instalado ou está desativado. Verifique a URL da loja e depois se o {company} Connector aparece como instalado e ativado em Extensions → Modules.',
'Oc_G_Q_No_Orders' => 'Os pedidos são feitos na loja, mas levam minutos para aparecer',
'Oc_G_A_No_Orders' => 'A loja não consegue acessar este espaço de trabalho, então os pedidos só chegam pela verificação agendada. Veja o endereço do {company} na página do módulo: ele precisa ser acessível a partir do servidor da loja. Executar Testar conexão o registra novamente.',
'Oc_G_Q_Stock_Wrong' => 'Uma quantidade na loja está errada',
'Oc_G_A_Stock_Wrong' => 'Envie o estoque na aba Estoque, o que regrava todos os produtos vinculados com os números daqui. Se continuar divergindo, verifique se a opção de estoque está ativada e se ninguém está editando quantidades no OpenCart.',
'Oc_G_Q_Out_Of_Stock' => 'Um produto aparece sem estoque na loja, embora haja estoque aqui',
'Oc_G_A_Out_Of_Stock' => 'No OpenCart 3, um produto com várias opções mantém o estoque no produto como um todo; confira a quantidade do produto na loja, e não a das opções. Para qualquer produto, envie o estoque uma vez e veja os logs desse produto.',
'Oc_G_Q_Held' => 'Os logs dizem que um pedido foi retido',
'Oc_G_A_Held' => 'Um dos itens não corresponde a nenhum produto aqui e não pôde ser importado da loja, normalmente porque o produto foi excluído lá. Crie ou vincule o produto e depois importe os pedidos na aba Pedidos.',
'Oc_G_Q_Deleted_Sale' => 'Excluí uma venda importada e ela voltou',
'Oc_G_A_Deleted_Sale' => 'Enquanto o pedido estiver ativo na loja, o próximo aviso ou verificação o importa de novo. Em vez disso, cancele o pedido na loja, o que reverte a venda aqui.',
'Oc_G_Q_Uninstall' => 'Como desconecto a loja?',
'Oc_G_A_Uninstall' => 'Desative a sincronização na aba Conexão; nada se movimenta enquanto estiver desativada. Para remover a integração da loja, desinstale o {company} Connector em Extensions → Modules.',
'Oc_Full_Guide' => 'Abrir o guia completo',
'Comm_Receipt_Account_Hint' => 'A conta de caixa ou banco de onde sai este pagamento. O saldo dela diminui no valor e o razão lança Despesa de Comissão de Vendas contra ela.',
'Comm_G_Q_Ledger' => 'O que um pagamento de comissão faz na contabilidade?',
'Comm_G_A_Ledger' => 'Quando você cria um recibo e escolhe uma conta, o saldo dessa conta diminui no valor do recibo e, se os lançamentos automáticos estiverem ativados, é lançado um diário: débito em Despesa de Comissão de Vendas (5200-COMM), crédito na conta de caixa ou banco escolhida. Sem conta selecionada, o crédito vai para a conta Caixa padrão e nenhum saldo muda.',
'Hide_Zero_Decimals' => 'Ocultar decimais zerados',
'Sys_Hide_Zero_Decimals_Help' => 'Mostra valores inteiros sem os decimais: 100.00 vira 100, enquanto 100.50 mantém os decimais. Apenas exibição; os valores armazenados e os cálculos não mudam.',
'Sys_Currency_Position_Before_NoSpace' => 'Antes do valor, sem espaço',
